package com.grindstone.content.collectionlog;

import lombok.Getter;
import java.util.Arrays;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
public enum CollectionLogEntry {
    VETION_AND_CALVARION(502, "Vet'ion and Calvar'ion"),
    VENENATIS_AND_SPINDEL(501, "Venenatis and Spindel"),
    CHAMBERS_OF_XERIC(507, "Chambers of Xeric"),
    WINTERTODT(504, "Wintertodt"),
    CORPOREAL_BEAST(484, "Corporeal Beast"),
    HESPORI(541, "Hespori");

    private static final int COLLECTION_LOG_CONTAINER_ID = InventoryID.COLLECTION_TRANSMIT;
    private static final int TITLE_PARAM_ID = 689;
    private static final int ENUM_PARAM_ID = 690;

    @Getter
    private final int struct;
    private final String displayName;

    CollectionLogEntry(final int struct, String displayName) {
        this.struct = struct;
        this.displayName = displayName;
    }

    public String getTitle(Client client) {
        if (client == null || client.getStructComposition(struct) == null) {
            return displayName;
        }

        String title = client.getStructComposition(struct).getStringValue(TITLE_PARAM_ID);
        return title == null || title.trim().isEmpty() ? displayName : title;
    }

    public ItemComposition[] getItems(Client client) {
        if (client == null || client.getStructComposition(struct) == null) {
            return new ItemComposition[0];
        }

        int enumId = client.getStructComposition(struct).getIntValue(ENUM_PARAM_ID);
        if (enumId <= 0 || client.getEnum(enumId) == null || client.getEnum(enumId).getIntVals() == null) {
            return new ItemComposition[0];
        }

        int[] itemIds = client.getEnum(enumId).getIntVals();

        return Arrays.stream(itemIds)
                .mapToObj(client::getItemDefinition)
                .toArray(ItemComposition[]::new);
    }

    public boolean isObtained(Client client, ItemComposition item) {
        if (item == null) {
            return false;
        }

        return isObtained(client.getItemContainer(COLLECTION_LOG_CONTAINER_ID), item.getId());
    }

    public boolean isObtained(ItemContainer container, ItemComposition item) {
        return item != null && isObtained(container, item.getId());
    }

    public boolean isObtained(ItemContainer container, int itemId) {
        return container != null && itemId > 0 && container.contains(itemId);
    }

    public boolean isComplete(Client client) {
        ItemComposition[] items = getItems(client);
        ItemContainer container = client.getItemContainer(COLLECTION_LOG_CONTAINER_ID);

        if (items.length == 0) {
            return false;
        }

        for (ItemComposition item : items) {
            if (item != null && !isObtained(container, item.getId())) {
                return false;
            }
        }

        return true;
    }

    public boolean contains(Client client, int itemId) {
        if (client == null || client.getStructComposition(struct) == null) {
            return false;
        }

        int enumId = client.getStructComposition(struct).getIntValue(ENUM_PARAM_ID);
        return enumId > 0 && client.getEnum(enumId) != null && client.getEnum(enumId).getIntVals() != null && Arrays.stream(client.getEnum(enumId).getIntVals()).anyMatch(id -> id == itemId);
    }
}

package com.grindstone.content.collectionlog;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
public final class CollectionLogHistory {
    private static final DateTimeFormatter FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm z");
    private final Map<Integer, Long> firstSeen = new HashMap<>();
    @Getter
    private long snapshotAt;
    @Getter
    private int snapshotCount;

    public boolean hasSnapshot() {
        return snapshotAt > 0;
    }

    public boolean reconcileItems(Set<Integer> validItems) {
        Map<Integer, Long> normalized = new HashMap<>();
        firstSeen.forEach((item, time) -> {
            int canonical = CollectionLogPages.getCanonicalItemId(item);
            if (validItems == null || validItems.contains(canonical)) {
                normalized.merge(canonical, time, Math::min);
            }
        });
        if (normalized.equals(firstSeen)) {
            return false;
        }
        firstSeen.clear();
        firstSeen.putAll(normalized);
        snapshotAt = 0;
        snapshotCount = 0;
        return true;
    }

    public boolean confirmLoadedSnapshot(int total, int maximum, long now) {
        if (maximum <= 0 || total < 0 || total > maximum || firstSeen.size() != total || hasSnapshot() && snapshotCount == total) {
            return false;
        }
        restoreSnapshot(now, total);
        return true;
    }

    public void restoreSnapshot(long at, int count) {
        if (at <= 0 || count < 0 || count > firstSeen.size()) {
            throw new IllegalArgumentException("Invalid collection-log snapshot.");
        }
        snapshotAt = at;
        snapshotCount = count;
    }

    public void observe(ItemContainer container) {
        if (container == null || container.getId() != InventoryID.COLLECTION_TRANSMIT) {
            return;
        }
        long now = System.currentTimeMillis();
        for (Item item : container.getItems()) {
            if (item != null && item.getId() > 0 && item.getQuantity() > 0) {
                record(item.getId(), now);
            }
        }
    }

    public void record(int itemId, long epochMillis) {
        if (itemId <= 0 || epochMillis <= 0) {
            return;
        }
        firstSeen.merge(CollectionLogPages.getCanonicalItemId(itemId), epochMillis, Math::min);
    }

    public boolean contains(int itemId) {
        return firstSeen.containsKey(CollectionLogPages.getCanonicalItemId(itemId));
    }

    public Long getFirstSeenAt(int itemId) {
        return firstSeen.get(CollectionLogPages.getCanonicalItemId(itemId));
    }

    public int getKnownUnlockCount() {
        return firstSeen.size();
    }

    public Map<Integer, Long> getSnapshot() {
        return Collections.unmodifiableMap(new HashMap<>(firstSeen));
    }

    public String getFirstSeenText(int itemId) {
        Long time = getFirstSeenAt(itemId);
        return time == null ? "Not yet observed in your collection log" : "First seen: " + FORMAT.format(Instant.ofEpochMilli(time).atZone(ZoneId.systemDefault()));
    }
}

package com.grindstone.content.collectionlog;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.ItemComposition;
import net.runelite.api.StructComposition;
import net.runelite.api.gameval.ItemID;
/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class CollectionLogPages {
    private static final int TABS_ENUM = 2102;
    private static final int ITEM_REPLACEMENTS_ENUM = 3721;
    private static volatile Map<Integer, Integer> replacements = Collections.emptyMap();
    private static final int TAB_PAGES_PARAM = 683;
    private static final int PAGE_TITLE_PARAM = 689;
    private static final int PAGE_ITEMS_PARAM = 690;
    private CollectionLogPages() {
    }
    public static void refreshReplacements(Client client) {
        EnumComposition mapping = client.getEnum(ITEM_REPLACEMENTS_ENUM);
        if (mapping == null || mapping.getKeys() == null || mapping.getIntVals() == null || mapping.getKeys().length != mapping.getIntVals().length) {
            return;
        }
        Map<Integer, Integer> values = new HashMap<>();
        for (int index = 0; index < mapping.getKeys().length; index++) {
            if (mapping.getKeys()[index] > 0 && mapping.getIntVals()[index] > 0) {
                values.put(mapping.getKeys()[index], mapping.getIntVals()[index]);
            }
        }
        replacements = Collections.unmodifiableMap(values);
    }

    public static int getCanonicalItemId(int item) {
        Integer replacement = replacements.get(item);
        if (replacement != null) {
            return replacement;
        }
        switch (item) {
            case ItemID.FOSSIL_MOTHERLODE_REWARD_HAT: return ItemID.MOTHERLODE_REWARD_HAT;
            case ItemID.FOSSIL_MOTHERLODE_REWARD_TOP: return ItemID.MOTHERLODE_REWARD_TOP;
            case ItemID.FOSSIL_MOTHERLODE_REWARD_LEGS: return ItemID.MOTHERLODE_REWARD_LEGS;
            case ItemID.FOSSIL_MOTHERLODE_REWARD_BOOTS: return ItemID.MOTHERLODE_REWARD_BOOTS;
            case ItemID.TOL_TEA: return ItemID.TOL_TEA_DUMMY;
            case ItemID.TOL_PLAIN_SACK: return ItemID.TOL_PLAIN_SACK_DUMMY;
            case ItemID.TOL_GREEN_SACK: return ItemID.TOL_GREEN_SACK_DUMMY;
            case ItemID.TOL_RED_SACK: return ItemID.TOL_RED_SACK_DUMMY;
            case ItemID.TOL_BLACK_SACK: return ItemID.TOL_BLACK_SACK_DUMMY;
            case ItemID.TOL_GOLD_SACK: return ItemID.TOL_GOLD_SACK_DUMMY;
            case ItemID.TOL_RUNE_SACK: return ItemID.TOL_RUNE_SACK_DUMMY;
            case ItemID.ABYSSALSIRE_UNSIRED: return ItemID.ABYSSALSIRE_UNSIRED_DUMMY;
            case ItemID.COAL_BAG: return ItemID.COAL_BAG_DUMMY;
            case ItemID.GEM_BAG: return ItemID.GEM_BAG_DUMMY;
            case ItemID.PLANK_SACK: return ItemID.PLANK_SACK_DUMMY;
            case ItemID.FLAMTAER_BAG: return ItemID.FLAMTAER_BAG_DUMMY;
            default: return item;
        }
    }
    public static Map<Integer, String> getTabs(Client client) {
        Map<Integer, String> tabs = new LinkedHashMap<>();
        if (client == null) {
            tabs.put(471, "Bosses");
            tabs.put(472, "Raids");
            tabs.put(473, "Clues");
            tabs.put(474, "Minigames");
            tabs.put(475, "Other");
            return Collections.unmodifiableMap(tabs);
        }
        EnumComposition entries = client.getEnum(TABS_ENUM);
        if (entries != null && entries.getIntVals() != null) {
            for (int id : entries.getIntVals()) {
                StructComposition tab = client.getStructComposition(id);
                String name = tab == null ? null : tab.getStringValue(682);
                if (id > 0 && name != null && !name.trim().isEmpty() && !"null".equals(name)) {
                    tabs.put(id, name);
                }
            }
        }
        return Collections.unmodifiableMap(tabs);
    }

    public static int[] getTabItemIds(Client client, int tabStruct) {
        StructComposition tab = client == null ? null : client.getStructComposition(tabStruct);
        int pagesEnum = tab == null ? 0 : tab.getIntValue(TAB_PAGES_PARAM);
        EnumComposition pages = pagesEnum <= 0 ? null : client.getEnum(pagesEnum);
        if (pages == null || pages.getIntVals() == null) {
            return new int[0];
        }
        return Arrays.stream(pages.getIntVals()).filter(id -> id > 0).flatMap(page -> Arrays.stream(getItemIds(client, page))).distinct().toArray();
    }

    public static Map<Integer, String> discover(Client client) {
        Map<Integer, String> pages = new LinkedHashMap<>();
        if (client == null) {
            return pages;
        }
        refreshReplacements(client);
        EnumComposition tabs = client.getEnum(TABS_ENUM);
        if (tabs == null || tabs.getIntVals() == null) {
            return pages;
        }
        for (int id : tabs.getIntVals()) {
            StructComposition tab = client.getStructComposition(id);
            if (tab == null) {
                continue;
            }
            EnumComposition entries = client.getEnum(tab.getIntValue(TAB_PAGES_PARAM));
            if (entries == null || entries.getIntVals() == null) {
                continue;
            }
            for (int page : entries.getIntVals()) {
                if (page <= 0) {
                    continue;
                }
                String name = getTitle(client, page, "");
                if (!name.isEmpty()) {
                    pages.put(page, name);
                }
            }
        }
        return Collections.unmodifiableMap(pages);
    }
    public static String getTitle(Client client, int page, String fallback) {
        StructComposition struct = client == null ? null : client.getStructComposition(page);
        String name = struct == null ? null : struct.getStringValue(PAGE_TITLE_PARAM);
        return name == null || name.trim().isEmpty() || "null".equals(name) ? fallback : name;
    }
    public static int[] getItemIds(Client client, int page) {
        StructComposition struct = client == null ? null : client.getStructComposition(page);
        if (struct == null) {
            return new int[0];
        }
        int enumId = struct.getIntValue(PAGE_ITEMS_PARAM);
        EnumComposition items = enumId <= 0 ? null : client.getEnum(enumId);
        return items == null || items.getIntVals() == null ? new int[0] : Arrays.stream(items.getIntVals()).filter(id -> id > 0).map(CollectionLogPages::getCanonicalItemId).distinct().toArray();
    }
    public static ItemComposition[] getItems(Client client, int page) {
        if (client == null) {
            return new ItemComposition[0];
        }
        return Arrays.stream(getItemIds(client, page)).mapToObj(client::getItemDefinition).filter(Objects::nonNull).toArray(ItemComposition[]::new);
    }
}

package com.grindstone.content.combatachievement;
import java.util.ArrayList;
import java.util.Collections;
