import net.runelite.api.gameval.VarPlayerID;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/20/2026
 */
public final class CollectionLogTotalMilestone extends ClientCompletionMilestone {
    private long target = 100;
    @Getter
    private transient int collectionMaximum;
    @Getter
    private transient boolean loaded;

    @Override
    public String selectionKey() {
        return "collection-total";
    }

    @Override
    public boolean supportsTarget() {
        return true;
    }

    @Override
    public void setTarget(long target) {
        if (target < 1 || target > Integer.MAX_VALUE) {
            throw new IllegalArgumentException("Choose a positive collection-log unlock target.");
        }
        this.target = target;
        if (loaded) {
            update(getProgressCurrent(), target, getProgressCurrent() > 0);
        }
    }

    @Override
    public String getTitle(Client client) {
        return "Total collection-log unlocks";
    }

    @Override
    public String getDescription() {
        return "Reach a total number of collection-log unlocks across all pages. Uses the game's total counter, not item quantities or a sum of page totals. Open your collection log if the total has not loaded.";
    }

    @Override
    public MilestoneCategory getCategory() {
        return MilestoneCategory.COLLECTION_LOG;
    }

    @Override
    public long getProgressMaximum() {
        return target;
    }

    @Override
    public String getProgressText() {
        return loaded ? String.format(Locale.ROOT, "%,d / %,d unlocks", getProgressCurrent(), target) : "Open your collection log to load the total";
    }

    @Override
    public boolean refresh(Client client) {
        int maximum = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
        int current = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
        boolean nextLoaded = maximum > 0 && current >= 0 && current <= maximum;
        boolean changed = loaded != nextLoaded || collectionMaximum != maximum;
        loaded = nextLoaded;
        collectionMaximum = Math.max(0, maximum);
        return update(loaded ? current : 0, loaded ? target : 0, loaded && current > 0) || changed;
    }

    @Override
    public Supplier<MilestoneComponent> prepare(Client client, GrindstoneConfig config) {
        refresh(client);
        return super.prepare(client, config);
    }
}

package com.grindstone.content.milestone.impl.combatachievement;
import com.grindstone.content.combatachievement.CombatAchievementData;
import com.grindstone.content.milestone.ClientCompletionMilestone;
import com.grindstone.content.milestone.MilestoneCategory;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import net.runelite.api.Client;
/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
public final class CombatAchievementBossMilestone extends ClientCompletionMilestone {
    private int boss;
    private final String name;
    private transient List<Integer> tasks;
    public CombatAchievementBossMilestone(int boss, String name) {
        if (boss < 0) {
            throw new IllegalArgumentException("Invalid boss");
        }
        this.boss = boss;
        this.name = Objects.requireNonNull(name);
    }
    public CombatAchievementBossMilestone(String name) {
        this.boss = -1;
        this.name = Objects.requireNonNull(name).trim();
        if (this.name.isEmpty()) {
            throw new IllegalArgumentException("Boss name is required");
        }
    }
    public boolean matches(CombatAchievementBossMilestone other) {
        return boss >= 0 && other.boss >= 0 ? boss == other.boss : name.equalsIgnoreCase(other.name);
    }
    @Override
    public String selectionKey() {
        Objects.requireNonNull(name);
        if (boss < -1 || name.trim().isEmpty()) {
            throw new IllegalArgumentException("Invalid boss");
        }
        return boss >= 0 ? Integer.toString(boss) : "name:" + name.toLowerCase(Locale.ROOT);
    }
    @Override
    public String getTitle(Client client) {
        return name + " combat achievements";
    }
    @Override
    public String getDescription() {
        return "Complete every combat achievement for this boss or activity.";
    }
    @Override
    public MilestoneCategory getCategory() {
        return MilestoneCategory.COMBAT_ACHIEVEMENT;
    }
    @Override
    public boolean refresh(Client client) {
        if (boss < 0) {
            for (int candidate : CombatAchievementData.getTasksByBoss(client).keySet()) {
                if (name.equalsIgnoreCase(CombatAchievementData.getBossName(client, candidate))) {
                    boss = candidate;
                    break;
                }
            }
            if (boss < 0) {
                return update(0, 0, false);
            }
        }
        if (tasks == null || tasks.isEmpty()) {
            tasks = CombatAchievementData.getTaskIds(client, boss);
        }
        long done = tasks.stream().filter(task -> CombatAchievementData.isComplete(client, task)).count();
        return update(done, tasks.size(), done > 0);
    }
    @Override
    public String getProgressText() {
        return hasProgress() ? super.getProgressText() + " tasks" : "Waiting for client task data";
    }
}

