    CLUES_TOTAL("Clue scrolls completed", VarPlayerID.COMPLETED_CLUES_TOTAL, MilestoneCategory.CLUES);
    private static final Map<String, TrackerEntry> BOSS_TRACKERS = new HashMap<>();
    static {
        for (TrackerEntry entry : values()) {
            if ((entry.category == MilestoneCategory.BOSSING || entry.category == MilestoneCategory.SKILLING || entry == WINTERTODT || entry == TEMPOROSS || entry == MIMIC) && entry.displayName.endsWith(" kills")) {
                BOSS_TRACKERS.put(normalized(entry.displayName.substring(0, entry.displayName.length() - 6)), entry);
            }
        }
    }
    private final String displayName;
    @Getter
    private final int id;
    @Getter
    private final MilestoneCategory category;
    @Getter
    private final boolean varbit;
    @Getter
    private final int defaultTarget;
    private int representativeItem;
    private boolean iconResolved;
    TrackerEntry(String displayName, int id, MilestoneCategory category) {
        this.displayName = displayName;
        this.id = id;
        this.category = category;
        this.varbit = false;
        this.defaultTarget = 5000;
    }
    TrackerEntry(String displayName, int id, boolean varbit, int defaultTarget) {
        this.displayName = displayName;
        this.id = id;
        this.category = MilestoneCategory.SLAYER;
        this.varbit = varbit;
        this.defaultTarget = defaultTarget;
    }
    public String getDisplayName() {
        switch (this) {
            case LMS_SCORE:
                return "Last Man Standing (Score)";
            case SOUL_WARS_KILLS:
                return "Soul Wars (Kills)";
            case SOUL_WARS_DEATHS:
                return "Soul Wars (Deaths)";
            case SOUL_WARS_GAMES:
                return "Soul Wars (Games)";
            case SOUL_WARS_WINS:
                return "Soul Wars (Wins)";
            case GOTR:
                return "Guardians of the Rift";
            case MIXOLOGY_ORDERS:
                return "Mastering Mixology (Orders)";
            case SLAYER_POINTS:
                return "Slayer (Points)";
            case SLAYER_STREAK:
                return "Slayer (Normal Task Streak)";
            case SLAYER_WILDERNESS_STREAK:
                return "Slayer (Wilderness Task Streak)";
            case CLUES_TOTAL:
                return "Clue Scrolls (Total)";
            case COLOSSEUM_WAVES:
                return "Fortis Colosseum (Waves)";
            case DOM_LEVELS:
                return "Doom of Mokhaiotl (Delve Levels)";
            case PERILOUS_MOONS:
                return "Moons of Peril";
            default:
                return displayName.replaceFirst("(?: kills| completions| chests)$", "").replaceFirst(": (.+)$", " ($1)");
        }
    }
    public boolean isSelectable() {
        return this != SOUL_WARS_DEATHS && this != COLOSSEUM_WAVES && this != SPEEDRUNS;
    }
    public String getDescription() {
        if (this == LMS_SCORE) {
            return "Current competitive Last Man Standing score, not wins or reward points. Your score can decrease. Play a competitive game to refresh the client reading.";
        }
        if (this == SLAYER_POINTS) {
            return "Current unspent Slayer reward points, not lifetime points earned. Spending points reduces progress. Open Slayer rewards to refresh the client reading.";
        }
        if (this == SLAYER_STREAK || this == SLAYER_WILDERNESS_STREAK) {
            return "Current " + (this == SLAYER_STREAK ? "normal" : "Wilderness") + " Slayer task streak, tracked separately. Resetting this streak reduces progress; this is not a lifetime task total. Check your Slayer information or complete a task to refresh the client reading.";
        }
        return "";
    }
    public Icon getIcon() {
        return category.getIcon();
    }
    public static TrackerEntry forBossName(String name) {
        if (name == null || name.trim().isEmpty()) {
            return null;
        }
        return BOSS_TRACKERS.get(normalized(name));
    }
    public int getCount(Client client) {
        return readCount(client::getVarpValue, client::getVarbitValue);
    }
    int readCount(IntUnaryOperator varps, IntUnaryOperator varbits) {
        return Math.max(0, (varbit ? varbits : varps).applyAsInt(id));
    }
    public int getIconItem(Client client) {
        if (category == MilestoneCategory.SLAYER || category == MilestoneCategory.CLUES) {
            return 0;
        }
        if (representativeItem > 0 || iconResolved || client == null) {
            return representativeItem;
        }
        Map<Integer, String> pages = CollectionLogPages.discover(client);
        if (!pages.isEmpty()) {
            iconResolved = true;
        }
        String name = normalized(displayName);
        int best = 0;
        for (Map.Entry<Integer, String> page : pages.entrySet()) {
            String candidate = normalized(page.getValue());
            if (candidate.length() > best && (name.startsWith(candidate) || candidate.startsWith(name))) {
                int[] items = CollectionLogPages.getItemIds(client, page.getKey());
                if (items.length > 0) {
                    representativeItem = items[0];
                    best = candidate.length();
                }
            }
        }
        return representativeItem;
    }
    private static String normalized(String text) {
        return text.toLowerCase(Locale.ROOT).replaceFirst("^the ", "").replaceAll("[^a-z0-9]", "");
    }
}

package com.grindstone.notification;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class CompletionTransitions {
    private final Map<String, String> cycles = new HashMap<>();
    private final Map<String, Boolean> reached = new HashMap<>();

    public boolean observe(String id, String cycle, boolean complete) {
        String previous = cycles.put(id, cycle);
        if (!cycle.equals(previous)) {
            reached.put(id, complete);
            return false;
        }
        boolean alreadyReached = Boolean.TRUE.equals(reached.get(id));
        if (complete) {
            reached.put(id, true);
        }
        return complete && !alreadyReached;
    }

    public void retain(Set<String> ids) {
        cycles.keySet().retainAll(ids);
        reached.keySet().retainAll(ids);
    }

    public void clear() {
        cycles.clear();
        reached.clear();
    }
}

package com.grindstone.notification;

import com.grindstone.config.GrindstoneConfig;
import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.MilestoneStatus;
import com.grindstone.content.milestone.TrackingState;
import com.grindstone.repository.MilestoneMetadata;
import com.grindstone.repository.GrindstoneProfile;
import com.grindstone.repository.RecurringMilestone;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
@Singleton
public final class MilestoneCompletionNotifications {
    private final CompletionTransitions transitions = new CompletionTransitions();
    @Inject
    private GrindstoneConfig config;
    @Inject
    private Client client;
    @Inject
    private MilestoneCompletionOverlay overlay;
    @Inject
    private ChatMessageManager chat;
    @Inject
    private Notifier notifier;
    @Inject
    private RoutineReminders reminders;
    private GrindstoneProfile profile;

    public synchronized void reset() {
        profile = null;
        transitions.clear();
        overlay.clear();
    }

    public synchronized void stop() {
        reset();
        reminders.clear();
    }

    public synchronized void observe(GrindstoneProfile active) {
        if (profile != active) {
            reset();
            profile = active;
        }
        reminders.observe(active);
        Set<String> ids = new HashSet<>();
        List<String> completed = new ArrayList<>();
        List<String> details = new ArrayList<>();
        List<String> headings = new ArrayList<>();
        int routineCompletions = 0;
        for (Milestone goal : active.getGoals()) {
            MilestoneMetadata metadata = active.getMetadata(goal);
            RecurringMilestone recurring = metadata.getRecurring();
            String id = metadata.getId();
            ids.add(id);
            if (TrackingState.of(goal, recurring, true, active.getPlayerStorage().hasBankSnapshot()) == TrackingState.WAITING) {
                continue;
            }
            boolean repeating = recurring.isActive() && RecurringMilestone.supports(goal);
            long target = repeating ? recurring.getTarget() : goal.getProgressMaximum();
            String cycle = target + ":" + (repeating ? recurring.getSchedule() + ":" + recurring.getStart() : "once");
            boolean complete = (repeating ? recurring.getStatus() : goal.getStatus()) == MilestoneStatus.COMPLETE;
            if (transitions.observe(id, cycle, complete)) {
                String title = NotificationMessages.formatTitle(goal.getTitle(client));
                String label = (repeating ? recurring.getSchedule() + ": " : "") + title;
                completed.add(label);
                headings.add(repeating ? "Routine complete" : "Milestone complete");
                details.add(label + (config.completionNumbers() ? NotificationMessages.formatProgress(goal, repeating ? recurring.getProgress() : goal.getProgressCurrent(), target) : ""));
                if (repeating) {
                    routineCompletions++;
                }
            }
        }
        transitions.retain(ids);
        if (completed.isEmpty()) {
            return;
        }
        if (config.completionPopup()) {
            overlay.show(completed, routineCompletions == completed.size());
        }
        boolean routinesOnly = routineCompletions == completed.size();
        String heading = completed.size() == 1 ? (routinesOnly ? "Routine complete" : "Milestone complete") : completed.size() + (routinesOnly ? " routines complete" : " targets reached");
        String detail = String.join("; ", details.subList(0, Math.min(3, details.size()))) + (details.size() > 3 ? "; and " + (details.size() - 3) + " more" : "");
        String message = heading + ": " + detail;
        if (config.completionChat()) {
            for (int index = 0; index < Math.min(5, details.size()); index++) {
                chat.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).value(NotificationMessages.formatChat(headings.get(index), details.get(index), config.notificationColours(), true)).build());
            }
            if (details.size() > 5) {
                chat.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).value(NotificationMessages.formatChat("More targets reached", (details.size() - 5) + " more complete. Open History in Grindstone to view them.", config.notificationColours(), true)).build());
            }
        }
        if (config.completionNotification().isEnabled()) {
            notifier.notify(config.completionNotification(), message);
        }
    }
}

package com.grindstone.notification;

import com.grindstone.config.GrindstoneConfig;
import com.grindstone.overlay.OverlayStyle;
import com.grindstone.ui.Icon;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.util.Text;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
@Singleton
public final class MilestoneCompletionOverlay extends Overlay {
    private static final int WIDTH = 300;
    private final GrindstoneConfig config;
    private volatile Popup popup;

    @Inject
    public MilestoneCompletionOverlay(GrindstoneConfig config) {
        this.config = config;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
    }

    public void show(List<String> titles) {
        show(titles, false);
    }

    public synchronized void show(List<String> titles, boolean routinesOnly) {
        if (titles.isEmpty()) {
            return;
        }
        long now = System.nanoTime();
        Popup previous = popup;
        Set<String> combined = new LinkedHashSet<>();
        if (previous != null && now - previous.startedAt < previous.duration) {
            combined.addAll(previous.titles);
            routinesOnly &= previous.routinesOnly;
        }
        for (String title : titles) {
            if (combined.size() >= 50) {
                break;
            }
            combined.add(Text.removeTags(title).replaceAll("[\\r\\n\\t]", " ").trim());
        }
        popup = new Popup(List.copyOf(combined), routinesOnly, now, Math.max(3, Math.min(15, config.completionPopupSeconds())) * 1_000_000_000L);
    }

    public synchronized void clear() {
        popup = null;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Popup current = popup;
        if (!config.enabled() || !config.completionPopup() || current == null) {
            return null;
        }
        long age = System.nanoTime() - current.startedAt;
        if (age >= current.duration) {
            return null;
        }
        int shown = Math.min(3, current.titles.size());
        int height = 100 + shown * 20 + (current.titles.size() > shown ? 18 : 0);
        float alpha = (float) Math.max(0, Math.min(1, Math.min(age / 160_000_000.0, (current.duration - age) / 450_000_000.0)));
        Graphics2D card = (Graphics2D) graphics.create();
        try {
            card.setComposite(AlphaComposite.SrcOver.derive(alpha));
            OverlayStyle.frame(card, WIDTH, height, OverlayStyle.GREEN);
            card.drawImage(Icon.MAIN.getImage(), 15, 16, 22, 22, null);
            card.setFont(FontManager.getRunescapeSmallFont());
            card.setColor(OverlayStyle.MUTED);
            card.drawString("GRINDSTONE", 46, 23);
            card.setFont(FontManager.getRunescapeBoldFont());
            card.setColor(OverlayStyle.GOLD);
            String heading = current.titles.size() == 1 ? current.routinesOnly ? "Routine complete!" : "Milestone reached!" : current.titles.size() + " targets reached!";
            card.drawString(heading, 46, 40);
            card.setColor(new Color(37, 69, 49));
            card.fillOval(WIDTH - 40, 16, 23, 23);
            OverlayStyle.check(card, WIDTH - 33, 23, OverlayStyle.GREEN);
            card.setColor(new Color(80, 83, 88, 100));
            card.drawLine(14, 49, WIDTH - 18, 49);
            card.setFont(FontManager.getRunescapeBoldFont());
            card.setColor(OverlayStyle.TEXT);
            for (int index = 0; index < shown; index++) {
                card.drawString(OverlayStyle.fit(current.titles.get(index), card.getFontMetrics(), WIDTH - 32), 15, 68 + index * 20);
            }
            card.setFont(FontManager.getRunescapeSmallFont());
            if (current.titles.size() > shown) {
                card.setColor(OverlayStyle.MUTED);
                card.drawString("And " + (current.titles.size() - shown) + " more", 15, 68 + shown * 20);
            }
            card.setColor(OverlayStyle.GREEN);
            card.drawString("Complete", 15, height - 29);
            card.drawString("100%", WIDTH - 18 - card.getFontMetrics().stringWidth("100%"), height - 29);
            OverlayStyle.progress(card, 15, height - 19, WIDTH - 34, 1, OverlayStyle.GREEN);
        } finally {
            card.dispose();
        }
        return new Dimension(WIDTH, height);
    }

    /**
