/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/20/2026
 */
public final class NotificationMessages {
    private NotificationMessages() {
    }

    public static String formatTitle(String title) {
        String clean = Text.removeTags(title).replaceAll("[\\r\\n\\t]", " ").trim();
        if (clean.isEmpty()) {
            return "Personal milestone";
        }
        return clean.length() > 100 ? clean.substring(0, 97) + "..." : clean;
    }

    public static String formatProgress(long current, long target) {
        return target > 0 ? String.format(Locale.ROOT, " (%,d / %,d)", Math.max(0, current), target) : "";
    }

    public static String formatProgress(Milestone goal, long current, long target) {
        String numbers = formatProgress(current, target);
        if (!numbers.isEmpty() && (goal instanceof SkillExperienceMilestone || goal instanceof TotalExperienceMilestone || goal instanceof BaseExperienceMilestone || goal instanceof SessionExperienceMilestone)) {
            return numbers.substring(0, numbers.length() - 1) + " XP)";
        }
        return numbers;
    }

    public static String formatChat(String heading, String detail, boolean colours, boolean complete) {
        if (!colours) {
            return "[Grindstone] " + heading + ": " + detail;
        }
        return ColorUtil.wrapWithColorTag("[Grindstone] ", new Color(178, 112, 18)) + ColorUtil.wrapWithColorTag(heading + ": ", complete ? new Color(0, 125, 55) : new Color(165, 80, 15)) + ColorUtil.wrapWithColorTag(detail, new Color(35, 100, 155));
    }
}

package com.grindstone.notification;

import com.grindstone.config.GrindstoneConfig;
import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.MilestoneStatus;
import com.grindstone.content.milestone.TrackingState;
import com.grindstone.overlay.OverlayStyle;
import com.grindstone.repository.GrindstoneProfile;
import com.grindstone.repository.RecurringMilestone;
import com.grindstone.repository.RepeatSchedule;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.Notifier;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/20/2026
 */
@Singleton
public final class RoutineReminders {
    @Inject
    private GrindstoneConfig config;
    @Inject
    private Client client;
    @Inject
    private ChatMessageManager chat;
    @Inject
    private Notifier notifier;
    private final Map<RepeatSchedule, Long> lastReminded = new EnumMap<>(RepeatSchedule.class);
    private final Map<RepeatSchedule, Long> periods = new EnumMap<>(RepeatSchedule.class);
    private long account;

    public void clear() {
        lastReminded.clear();
        periods.clear();
        account = 0;
    }

    public void observe(GrindstoneProfile profile) {
        if (!config.routineReminders() || (!config.routineReminderChat() && !config.routineReminderNotification().isEnabled())) {
            clear();
            return;
        }
        if (account != profile.getHash()) {
            clear();
            account = profile.getHash();
        }
        long now = System.currentTimeMillis();
        long interval = Math.max(5, Math.min(240, config.routineReminderMinutes())) * 60_000L;
        for (RepeatSchedule schedule : RepeatSchedule.values()) {
            if (!enabled(schedule)) {
                lastReminded.remove(schedule);
                periods.remove(schedule);
                continue;
            }
            long start = schedule.getPeriodStart(now);
            Long previousPeriod = periods.put(schedule, start);
            if (previousPeriod == null || previousPeriod != start) {
                boolean remindNow = previousPeriod == null ? config.routineReminderOnLogin() : config.routineReminderOnReset();
                lastReminded.put(schedule, remindNow ? 0L : now);
            }
            if (now - lastReminded.getOrDefault(schedule, now) < interval) {
                continue;
            }
            List<String> pending = new ArrayList<>();
            for (Milestone goal : profile.getGoals()) {
                RecurringMilestone routine = profile.getMetadata(goal).getRecurring();
                if (routine.getSchedule() != schedule || !RecurringMilestone.supports(goal) || routine.getStatus() == MilestoneStatus.COMPLETE || TrackingState.of(goal, routine, true, profile.getPlayerStorage().hasBankSnapshot()) == TrackingState.WAITING) {
                    continue;
                }
                pending.add(NotificationMessages.formatTitle(goal.getTitle(client)) + (config.routineReminderNumbers() ? NotificationMessages.formatProgress(goal, routine.getProgress(), routine.getTarget()) : ""));
            }
            if (pending.isEmpty()) {
                continue;
            }
            lastReminded.put(schedule, now);
            String heading = schedule + " reminder";
            String detail = pending.size() + (pending.size() == 1 ? " routine left: " : " routines left: ") + String.join("; ", pending.subList(0, Math.min(3, pending.size()))) + (pending.size() > 3 ? "; and " + (pending.size() - 3) + " more" : "") + "." + (config.routineReminderCountdown() ? " Resets in " + OverlayStyle.formatCountdown(schedule.getNextReset(start), now) + "." : "");
            if (config.routineReminderChat()) {
                chat.queue(QueuedMessage.builder().type(ChatMessageType.CONSOLE).value(NotificationMessages.formatChat(heading, detail, config.notificationColours(), false)).build());
            }
            if (config.routineReminderNotification().isEnabled()) {
                notifier.notify(config.routineReminderNotification(), heading + ": " + detail);
            }
        }
    }

    private boolean enabled(RepeatSchedule schedule) {
        switch (schedule) {
            case DAILY:
                return config.dailyReminders();
            case WEEKLY:
                return config.weeklyReminders();
            case MONTHLY:
                return config.monthlyReminders();
            default:
                return false;
        }
    }
}

package com.grindstone.overlay;

import com.grindstone.config.GrindstoneConfig;
import com.grindstone.config.ProgressOverlayView;
import com.grindstone.repository.RepeatSchedule;
import com.grindstone.ui.Icon;
import com.grindstone.util.NumberFormats;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/20/2026
 */
@Singleton
public final class GrindstoneProgressOverlay extends Overlay {
    private static final int HEADER_HEIGHT = 60;
    private static final int SECTION_HEIGHT = 20;
    private static final Color ROW_BACKGROUND = new Color(255, 255, 255, 8);
    private static final Color COMPLETED_BACKGROUND = new Color(104, 218, 151, 12);
    private static final Color DIVIDER = new Color(163, 168, 176, 40);
    private final GrindstoneConfig config;
    private volatile Snapshot snapshot;

    @Inject
    public GrindstoneProgressOverlay(GrindstoneConfig config) {
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_LOW);
    }

    public void clear() {
        snapshot = null;
    }

    public void update(List<ProgressOverlayEntry> entries, int canvasHeight) {
        if (!config.enabled() || !config.progressOverlayEnabled()) {
            clear();
            return;
        }
        ProgressOverlayView view = config.progressOverlayView();
        List<ProgressOverlayEntry> visible = new ArrayList<>();
        for (ProgressOverlayEntry entry : entries) {
            if (view.includes(entry.getSchedule(), entry.isPinned()) && (!entry.isComplete() || entry.getSchedule() != RepeatSchedule.NONE && config.progressOverlayCompletedRoutines())) {
                visible.add(entry);
            }
        }
        visible.sort(Comparator.comparingInt((ProgressOverlayEntry entry) -> order(entry.getSchedule())).thenComparing(ProgressOverlayEntry::isComplete).thenComparing(entry -> !entry.isPinned()).thenComparing(ProgressOverlayEntry::getTitle, String.CASE_INSENSITIVE_ORDER));
        boolean grouped = view == ProgressOverlayView.ALL || view == ProgressOverlayView.ROUTINES || view == ProgressOverlayView.PINNED;
        int rowHeight = config.progressOverlayBars() ? 44 : 36;
        int available = Math.max(1, (Math.max(180, canvasHeight) - HEADER_HEIGHT - 44) / (rowHeight + (grouped ? SECTION_HEIGHT : 0)));
        int limit = Math.max(1, Math.min(20, Math.min(config.progressOverlayRows(), available)));
        int completed = (int) visible.stream().filter(ProgressOverlayEntry::isComplete).count();
        snapshot = new Snapshot(List.copyOf(visible.subList(0, Math.min(limit, visible.size()))), view, visible.size(), completed, Math.max(180, Math.min(360, config.progressOverlayWidth())), config.progressOverlayBars(), grouped);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        Snapshot current = snapshot;
        if (!config.enabled() || !config.progressOverlayEnabled() || current == null || current.entries.isEmpty()) {
            return null;
        }
        int sections = 0;
        RepeatSchedule previous = null;
        for (ProgressOverlayEntry entry : current.entries) {
            if (current.grouped && previous != entry.getSchedule()) {
                sections++;
            }
            previous = entry.getSchedule();
        }
        int rowHeight = current.bars ? 44 : 36;
        int height = HEADER_HEIGHT + current.entries.size() * rowHeight + sections * SECTION_HEIGHT + (current.total > current.entries.size() ? 24 : 4);
        Graphics2D card = (Graphics2D) graphics.create();
        try {
            OverlayStyle.frame(card, current.width, height, OverlayStyle.GOLD);
            card.drawImage(Icon.MAIN.getImage(), 8, 8, 28, 28, null);
            card.setFont(FontManager.getRunescapeBoldFont());
            card.setColor(OverlayStyle.TEXT);
            card.drawString(current.view.getTitle(), 44, 21);
            card.setFont(FontManager.getRunescapeSmallFont());
            card.setColor(OverlayStyle.MUTED);
            card.drawString("Grindstone", 44, 35);
            long now = System.currentTimeMillis();
            String summary = current.completed + " / " + current.total + " complete";
            if (current.view == ProgressOverlayView.MILESTONES) {
                summary = current.total + " milestones tracked";
            } else if (current.view == ProgressOverlayView.DAILY) {
                summary += " · resets " + OverlayStyle.formatCountdown(RepeatSchedule.DAILY.getNextReset(RepeatSchedule.DAILY.getPeriodStart(now)), now);
            }
            card.drawString(OverlayStyle.fit(summary, card.getFontMetrics(), current.width - 20), 10, 51);
            int y = HEADER_HEIGHT;
            previous = null;
            for (ProgressOverlayEntry entry : current.entries) {
                if (current.grouped && previous != entry.getSchedule()) {
                    card.setFont(FontManager.getRunescapeSmallFont());
                    card.setColor(OverlayStyle.GOLD);
                    String section = entry.getSchedule() == RepeatSchedule.NONE ? "Milestones" : entry.getSchedule().toString();
                    card.drawString(section, 10, y + 11);
                    card.setColor(DIVIDER);
                    int lineStart = 18 + card.getFontMetrics().stringWidth(section);
                    card.drawLine(lineStart, y + 7, current.width - 10, y + 7);
                    y += SECTION_HEIGHT;
                }
                renderEntry(card, entry, current.width, y, current.bars);
                y += rowHeight;
                previous = entry.getSchedule();
            }
            if (current.total > current.entries.size()) {
                card.setFont(FontManager.getRunescapeSmallFont());
                card.setColor(OverlayStyle.MUTED);
                card.drawString((current.total - current.entries.size()) + " more in the sidebar", 10, y + 12);
            }
        } finally {
            card.dispose();
        }
        return new Dimension(current.width, height);
    }

    private static void renderEntry(Graphics2D graphics, ProgressOverlayEntry entry, int width, int y, boolean bars) {
        Color accent = entry.isComplete() ? OverlayStyle.GREEN : entry.isReady() ? OverlayStyle.GOLD : OverlayStyle.MUTED;
        graphics.setColor(entry.isComplete() ? COMPLETED_BACKGROUND : ROW_BACKGROUND);
        graphics.fillRoundRect(6, y, width - 12, bars ? 40 : 32, 6, 6);
        if (entry.isPinned()) {
            graphics.setColor(OverlayStyle.GOLD);
            graphics.fillRoundRect(6, y + 6, 2, bars ? 28 : 20, 2, 2);
        }
        int titleX = 14;
        if (entry.isComplete()) {
            OverlayStyle.check(graphics, 14, y + 4, accent);
            titleX = 28;
        }
        double ratio = entry.getTarget() <= 0 ? 0 : Math.max(0, Math.min(1, entry.getCurrent() / (double) entry.getTarget()));
        String percentage = entry.isReady() && entry.getTarget() > 0 ? Math.round(ratio * 100) + "%" : "";
        graphics.setFont(FontManager.getRunescapeSmallFont());
        int percentageWidth = graphics.getFontMetrics().stringWidth(percentage);
        graphics.setColor(accent);
        graphics.drawString(percentage, width - 14 - percentageWidth, y + 13);
        graphics.setFont(FontManager.getRunescapeBoldFont());
        graphics.setColor(entry.isComplete() ? OverlayStyle.GREEN : OverlayStyle.TEXT);
        graphics.drawString(OverlayStyle.fit(entry.getTitle(), graphics.getFontMetrics(), width - titleX - 14 - (percentage.isEmpty() ? 0 : percentageWidth + 10)), titleX, y + 13);
        graphics.setFont(FontManager.getRunescapeSmallFont());
        graphics.setColor(OverlayStyle.MUTED);
        String progress = entry.isReady() ? entry.getTarget() > 0 ? formatProgress(entry.getCurrent()) + " / " + formatProgress(entry.getTarget()) : entry.isComplete() ? "Complete" : "In progress" : "Waiting for game data";
        graphics.drawString(OverlayStyle.fit(progress, graphics.getFontMetrics(), width - 28), 14, y + 27);
        if (bars) {
            OverlayStyle.progress(graphics, 14, y + 33, width - 28, entry.isReady() ? ratio : 0, accent);
        }
    }

    private static String formatProgress(long value) {
        return value >= 1_000_000 ? NumberFormats.formatTarget(value) : String.format(Locale.ROOT, "%,d", value);
    }

    private static int order(RepeatSchedule schedule) {
        return schedule == RepeatSchedule.NONE ? 4 : schedule.ordinal();
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/20/2026
     */
    @Value
    private static class Snapshot {
        List<ProgressOverlayEntry> entries;
        ProgressOverlayView view;
        int total;
        int completed;
        int width;
        boolean bars;
        boolean grouped;
    }
}

package com.grindstone.overlay;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/20/2026
 */
public final class OverlayStyle {
    public static final Color BACKGROUND = new Color(23, 25, 29, 238);
    public static final Color BORDER = new Color(96, 88, 66, 210);
    public static final Color GOLD = new Color(230, 180, 83);
    public static final Color TEXT = new Color(238, 237, 229);
    public static final Color MUTED = new Color(163, 168, 176);
    public static final Color GREEN = new Color(104, 218, 151);
    public static final Color TRACK = new Color(55, 59, 65);

    private OverlayStyle() {
    }

    public static void frame(Graphics2D graphics, int width, int height, Color accent) {
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        graphics.setColor(BACKGROUND);
        graphics.fillRoundRect(0, 0, width, height, 10, 10);
        graphics.setColor(BORDER);
        graphics.drawRoundRect(0, 0, width - 1, height - 1, 10, 10);
        graphics.setColor(accent);
        graphics.fillRoundRect(11, 0, width - 26, 2, 2, 2);
    }

    public static void progress(Graphics2D graphics, int x, int y, int width, double fraction, Color color) {
        graphics.setColor(TRACK);
        graphics.fillRoundRect(x, y, width, 4, 4, 4);
        int filled = (int) Math.round(width * Math.max(0, Math.min(1, fraction)));
        if (filled > 0) {
            graphics.setColor(color);
            graphics.fillRoundRect(x, y, filled, 4, 4, 4);
        }
    }

    public static void check(Graphics2D graphics, int x, int y, Color color) {
        graphics.setColor(color);
        graphics.setStroke(new BasicStroke(1.7f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        graphics.drawLine(x, y + 4, x + 3, y + 7);
        graphics.drawLine(x + 3, y + 7, x + 9, y);
    }

    public static String fit(String text, FontMetrics metrics, int width) {
        if (metrics.stringWidth(text) <= width) {
            return text;
        }
        if (metrics.stringWidth("...") > width) {
            return "";
        }
        int start = 0;
        int end = text.length();
        while (start < end) {
            int middle = (start + end + 1) / 2;
            if (metrics.stringWidth(text.substring(0, middle) + "...") <= width) {
                start = middle;
            } else {
                end = middle - 1;
            }
        }
        end = start;
        if (end > 0 && Character.isHighSurrogate(text.charAt(end - 1))) {
            end--;
        }
        return text.substring(0, end) + "...";
    }

    public static String formatCountdown(long resetAt, long now) {
        long seconds = Math.max(0, (resetAt - now + 999) / 1000);
        long days = seconds / 86_400;
        long hours = seconds / 3600 % 24;
        long minutes = seconds / 60 % 60;
        if (days > 0) {
            return days + "d " + hours + "h";
        }
        return hours > 0 ? hours + "h " + minutes + "m" : minutes > 0 ? minutes + "m" : seconds + "s";
    }
}

