package com.grindstone.repository;

import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.MilestoneCategory;
import com.grindstone.content.milestone.ManualMilestone;
import com.grindstone.content.milestone.impl.ChecklistMilestone;
import com.grindstone.content.milestone.impl.CustomMilestone;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class BulkMilestoneChanges {
    private BulkMilestoneChanges() {
    }

    public static Change apply(GrindstoneProfile profile, List<Milestone> selected, BulkMilestoneAction action, MilestoneCategory category, RepeatSchedule schedule, long target, long deadlineAt, boolean reminder, long now) {
        if (selected.isEmpty() || selected.size() > 5000 || new HashSet<>(selected).size() != selected.size() || !profile.getGoals().containsAll(selected) || action == null || now <= 0) {
            throw new IllegalArgumentException("Select existing milestones before applying a bulk action.");
        }
        if (action == BulkMilestoneAction.CATEGORY && category == null) {
            throw new IllegalArgumentException("Choose a category.");
        }
        if (action == BulkMilestoneAction.DEADLINE) {
            new MilestoneMetadata().setDeadline(deadlineAt, reminder);
        }
        if (action == BulkMilestoneAction.SCHEDULE) {
            if (schedule == null || target < 1 || target > Integer.MAX_VALUE) {
                throw new IllegalArgumentException("Choose a repeat schedule and positive period target.");
            }
            for (int i = 0; i < selected.size(); i++) {
                Milestone goal = selected.get(i);
                if (!RecurringMilestone.supports(goal)) {
                    throw new IllegalArgumentException(goal.getTitle(null) + " does not support repeat schedules. No milestones were changed.");
                }
                Milestone matching = profile.findMatchingGoal(goal, schedule);
                if (matching != null && matching != goal) {
                    throw new IllegalArgumentException("A matching tracker already has that schedule. No milestones were changed.");
                }
                for (int j = 0; j < i; j++) {
                    if (GrindstoneProfile.sameSelection(goal, selected.get(j))) {
                        throw new IllegalArgumentException("Two selected milestones would share the same subject and schedule. No milestones were changed.");
                    }
                }
            }
        }
        List<Milestone> originalOrder = new ArrayList<>(profile.getGoals());
        List<GrindstoneProfile.ArchivedHistory> originalArchives = new ArrayList<>(profile.getArchivedHistory());
        Map<Milestone, MilestoneMetadata> metadata = new LinkedHashMap<>();
        Map<Milestone, Consumer<Milestone>> restore = new LinkedHashMap<>();
        Map<RepeatSchedule, Long> periods = new LinkedHashMap<>();
        for (Milestone goal : selected) {
            MilestoneMetadata saved = profile.getMetadata(goal).copy();
            metadata.put(goal, saved);
            restore.put(goal, profile.snapshotEdit(goal));
            RepeatSchedule previous = saved.getRecurring().getSchedule();
            if (previous != RepeatSchedule.NONE) {
                periods.put(previous, previous.getPeriodStart(now));
            }
        }
        for (Milestone goal : selected) {
            MilestoneMetadata saved = profile.getMetadata(goal);
            switch (action) {
                case PIN:
                    saved.setPinned(true);
                    break;
                case UNPIN:
                    saved.setPinned(false);
                    break;
                case CATEGORY:
                    saved.setDisplayCategory(category);
                    break;
                case RESET_CATEGORY:
                    saved.setDisplayCategory(null);
                    break;
                case DEADLINE:
                    saved.setDeadline(deadlineAt, reminder);
                    break;
                case SCHEDULE:
                    long periodTarget = goal instanceof ChecklistMilestone ? goal.getProgressMaximum() : target;
                    boolean changed = saved.getRecurring().getSchedule() != schedule || saved.getRecurring().getTarget() != periodTarget;
                    saved.getRecurring().configure(schedule, periodTarget, now);
                    if (changed && schedule != RepeatSchedule.NONE && goal instanceof ManualMilestone) {
                        ((ManualMilestone) goal).resetProgress();
                    }
                    if (schedule != RepeatSchedule.NONE && goal instanceof CustomMilestone) {
                        goal.setTarget(periodTarget);
                    }
                    break;
                case DELETE:
                    profile.remove(goal);
                    break;
                default:
                    throw new IllegalArgumentException("Unsupported bulk action.");
            }
        }
        for (Milestone goal : selected) {
            RepeatSchedule current = profile.getMetadata(goal).getRecurring().getSchedule();
            if (current != RepeatSchedule.NONE) {
                periods.put(current, current.getPeriodStart(now));
            }
        }
        profile.touch();
        BooleanSupplier allowed = () -> periods.entrySet().stream().allMatch(entry -> entry.getKey().getPeriodStart(System.currentTimeMillis()) == entry.getValue());
        Runnable undo = () -> {
            if (!allowed.getAsBoolean()) {
                throw new IllegalStateException("A recurring period reset; this bulk edit can no longer be undone.");
            }
            if (action == BulkMilestoneAction.DELETE) {
                for (Milestone goal : selected) {
                    profile.add(goal, metadata.get(goal));
                }
                profile.replace(originalOrder);
                profile.restoreArchiveSnapshot(originalArchives);
            } else {
                restore.forEach((goal, operation) -> operation.accept(goal));
            }
            profile.touch();
        };
        return new Change(undo, allowed);
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/19/2026
     */
    public static final class Change {
        public final Runnable undo;
        public final BooleanSupplier allowed;

        private Change(Runnable undo, BooleanSupplier allowed) {
            this.undo = undo;
            this.allowed = allowed;
        }
    }
}

package com.grindstone.repository;

import com.grindstone.content.collectionlog.CollectionLogHistory;
import com.grindstone.content.milestone.ClientCompletionMilestone;
import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.impl.ChecklistMilestone;
import com.grindstone.content.milestone.impl.CustomMilestone;
import com.grindstone.content.milestone.impl.LinkedMilestone;
import com.grindstone.content.milestone.impl.TrackerMilestone;
import com.grindstone.content.milestone.impl.collectionlog.CollectionLogEntryMilestone;
import com.grindstone.content.milestone.impl.collectionlog.CollectionLogTabMilestone;
import com.grindstone.content.milestone.impl.collectionlog.CollectionLogItemMilestone;
import com.grindstone.content.milestone.impl.combatachievement.CombatAchievementBossMilestone;
import com.grindstone.content.milestone.impl.experience.SessionExperienceMilestone;
import com.grindstone.content.milestone.impl.experience.SkillExperienceMilestone;
import com.grindstone.content.milestone.impl.item.PossessedItemMilestone;
import com.grindstone.content.milestone.impl.level.SkillLevelMilestone;
import com.grindstone.content.storage.PlayerItemStorage;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.Consumer;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.game.ItemManager;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
public class GrindstoneProfile {
    @Getter
    private final long hash;
    private final List<Milestone> goals = new ArrayList<>();
    private final transient Map<Milestone, MilestoneMetadata> metadata = new IdentityHashMap<>();
    private transient long revision;
    private final Map<String, ArchivedHistory> archivedHistory = new LinkedHashMap<>();
    public Collection<ArchivedHistory> getArchivedHistory() {
        return Collections.unmodifiableCollection(archivedHistory.values());
    }
    public void restoreArchive(ArchivedHistory history) {
        if (history == null || history.title == null || history.title.length() > 300) {
            throw new IllegalArgumentException("Invalid archived history");
        }
        MilestoneMetadata.validated(history.metadata);
        if (goals.stream().noneMatch(goal -> getMetadata(goal).getId().equals(history.metadata.getId()))) {
            archivedHistory.putIfAbsent(history.metadata.getId(), history);
        }
        while (archivedHistory.size() > 500) {
            archivedHistory.remove(archivedHistory.keySet().iterator().next());
        }
    }
    public void restoreArchiveSnapshot(Collection<ArchivedHistory> histories) {
        if (histories.size() > 500) {
            throw new IllegalArgumentException("Too many archived histories.");
        }
        for (ArchivedHistory history : histories) {
            if (history == null || history.title == null || history.title.length() > 300) {
                throw new IllegalArgumentException("Invalid archived history.");
            }
            MilestoneMetadata.validated(history.metadata);
        }
        archivedHistory.clear();
        histories.forEach(this::restoreArchive);
    }
    private void archive(Milestone goal) {
        MilestoneMetadata saved = getMetadata(goal).copy();
        if (saved.getCompletions().isEmpty() && saved.getRecurring().getHistory().isEmpty() && saved.getRecurring().getBaselineAt() == 0) {
            return;
        }
        saved.getRecurring().stop(System.currentTimeMillis(), "Milestone archived · last observed");
        archivedHistory.put(saved.getId(), new ArchivedHistory(goal.getTitle(null), saved));
        while (archivedHistory.size() > 500) {
            archivedHistory.remove(archivedHistory.keySet().iterator().next());
        }
    }
    public long getRevision() {
        return revision;
    }
    public void touch() {
        revision++;
    }
    public Consumer<Milestone> snapshotEdit(Milestone original) {
        MilestoneMetadata saved = getMetadata(original).copy();
        RepeatSchedule previousSchedule = saved.getRecurring().getSchedule();
        long undoWindow = previousSchedule.getPeriodStart(System.currentTimeMillis());
        long target = original.getProgressMaximum();
        CustomMilestone custom = original instanceof CustomMilestone ? (CustomMilestone) original : null;
        CustomMilestone manual = custom == null ? null : new CustomMilestone(custom.getId(), custom.getTitle(null), custom.getDescription(), custom.getCategory(), custom.getProgressCurrent(), target);
        ChecklistMilestone checklist = original instanceof ChecklistMilestone ? (ChecklistMilestone) original : null;
        boolean[] savedChecks = checklist == null ? null : checklist.getChecks();
        return replacement -> {
            if (previousSchedule != RepeatSchedule.NONE && previousSchedule.getPeriodStart(System.currentTimeMillis()) != undoWindow) {
                throw new IllegalStateException("The previous period has reset.");
            }
            int index = goals.indexOf(replacement);
            if (index < 0) {
                throw new IllegalStateException("The edited milestone no longer exists.");
            }
            if (custom != null) {
                custom.update(manual.getTitle(null), manual.getDescription(), manual.getCategory(), manual.getProgressCurrent(), manual.getProgressMaximum());
            } else if (original.supportsTarget()) {
                original.setTarget(target);
            }
            if (checklist != null) {
                checklist.restoreChecks(savedChecks);
            }
            goals.set(index, original);
            if (original != replacement) {
                metadata.remove(replacement);
            }
            metadata.put(original, saved);
            archivedHistory.remove(saved.getId());
            attachCollectionData(original);
            touch();
        };
    }
    public MilestoneMetadata getMetadata(Milestone goal) {
        return metadata.computeIfAbsent(goal, ignored -> new MilestoneMetadata());
    }
    public void restoreMetadata(Milestone goal, MilestoneMetadata saved) {
        metadata.put(goal, MilestoneMetadata.validated(saved));
    }
    public void observeRecurring(Client client, long now) {
        for (Milestone goal : goals) {
            RecurringMilestone recurring = getMetadata(goal).getRecurring();
            if (recurring.isActive() && RecurringMilestone.supports(goal)) {
                goal.refresh(client);
                recurring.observe(goal, now);
            }
        }
        updateLinkedGoals(client != null && client.getGameState() == GameState.LOGGED_IN && client.getLocalPlayer() != null && client.getAccountHash() == hash);
    }
    public void updateLinkedGoals(boolean loggedIn) {
        Map<String, Milestone> sources = new HashMap<>();
        for (Milestone goal : goals) {
            if (!(goal instanceof LinkedMilestone)) {
                sources.put(getMetadata(goal).getId(), goal);
            }
        }
        for (Milestone goal : goals) {
            if (goal instanceof LinkedMilestone) {
                ((LinkedMilestone) goal).update(this, loggedIn, sources);
            }
        }
    }
    @Getter
    private final CollectionLogHistory collectionLogHistory = new CollectionLogHistory();
    private transient ItemManager itemManager;
    @Getter
    private final transient PlayerItemStorage playerStorage = new PlayerItemStorage();

    public GrindstoneProfile(long hash) {
        this(hash, null);
    }

    public GrindstoneProfile(long hash, ItemManager itemManager) {
        this.hash = hash;
        setItemManager(itemManager);
    }

    public void setItemManager(ItemManager itemManager) {
        this.itemManager = itemManager;
        for (Milestone goal : goals) {
            attachCollectionData(goal);
        }
    }

    private void attachCollectionData(Milestone goal) {
        if (goal instanceof TrackerMilestone) {
            ((TrackerMilestone) goal).setItemManager(itemManager);
        }
        if (goal instanceof PossessedItemMilestone) {
            ((PossessedItemMilestone) goal).attach(playerStorage, itemManager);
        }
        if (goal instanceof CollectionLogTabMilestone) {
            ((CollectionLogTabMilestone) goal).setHistory(collectionLogHistory);
        }
        if (goal instanceof CollectionLogEntryMilestone) {
            CollectionLogEntryMilestone entry = (CollectionLogEntryMilestone) goal;
            entry.setItemManager(itemManager);
            entry.setHistory(collectionLogHistory);
        } else if (goal instanceof CollectionLogItemMilestone) {
            CollectionLogItemMilestone item = (CollectionLogItemMilestone) goal;
            item.setItemManager(itemManager);
            item.setHistory(collectionLogHistory);
        }
    }

    public boolean add(Milestone goal) {
        return add(goal, new MilestoneMetadata());
    }

    public boolean add(Milestone goal, MilestoneMetadata details) {
        Objects.requireNonNull(goal, "goal");
        MilestoneMetadata.validated(details);
        if (findMatchingGoal(goal, details.getRecurring().getSchedule()) != null) {
            return false;
        }
        attachCollectionData(goal);
        metadata.put(goal, details);
        archivedHistory.remove(details.getId());
        touch();
        return goals.add(goal);
    }

    public Milestone findMatchingGoal(Milestone candidate) {
        return findMatchingGoal(candidate, RepeatSchedule.NONE);
    }

    public Milestone findMatchingGoal(Milestone candidate, RepeatSchedule schedule) {
        return goals.stream().filter(goal -> sameGoal(goal, candidate) && getMetadata(goal).getRecurring().getSchedule() == schedule).findFirst().orElse(null);
    }

    private static boolean sameGoal(Milestone left, Milestone right) {
        if (left.getClass() != right.getClass()) {
            return false;
        }
        if (left instanceof CombatAchievementBossMilestone) {
            return ((CombatAchievementBossMilestone) left).matches((CombatAchievementBossMilestone) right);
        }
        if (left instanceof PossessedItemMilestone) {
            return ((PossessedItemMilestone) left).getItem()
            == ((PossessedItemMilestone) right).getItem();
        }
        if (left instanceof ClientCompletionMilestone) {
            return ((ClientCompletionMilestone) left).selectionKey()
                    .equals(((ClientCompletionMilestone) right).selectionKey());
        }
        if (left instanceof CustomMilestone) {
            return ((CustomMilestone) left).getId().equals(((CustomMilestone) right).getId());
        }
        if (left instanceof ChecklistMilestone) {
            return ((ChecklistMilestone) left).getId().equals(((ChecklistMilestone) right).getId());
        }
        if (left instanceof LinkedMilestone) {
            return ((LinkedMilestone) left).getId().equals(((LinkedMilestone) right).getId());
        }
        if (left instanceof SkillLevelMilestone) {
            return ((SkillLevelMilestone) left).getSkill() == ((SkillLevelMilestone) right).getSkill();
        }
        if (left instanceof SkillExperienceMilestone) {
            return ((SkillExperienceMilestone) left).getSkill() == ((SkillExperienceMilestone) right).getSkill();
        }
        if (left instanceof SessionExperienceMilestone) {
            SessionExperienceMilestone first = (SessionExperienceMilestone) left;
            SessionExperienceMilestone second = (SessionExperienceMilestone) right;
            return first.isTotal() == second.isTotal() && first.getSkill() == second.getSkill();
        }
        if (left instanceof TrackerMilestone) {
            return ((TrackerMilestone) left).getTracker() == ((TrackerMilestone) right).getTracker();
        }
        if (left instanceof CollectionLogTabMilestone) {
            return ((CollectionLogTabMilestone) left).getTabStruct() == ((CollectionLogTabMilestone) right).getTabStruct();
        }
        if (left instanceof CollectionLogEntryMilestone) {
            return ((CollectionLogEntryMilestone) left).getPageStruct() == ((CollectionLogEntryMilestone) right).getPageStruct();
        }
        if (left instanceof CollectionLogItemMilestone) {
            return ((CollectionLogItemMilestone) left).getItem() == ((CollectionLogItemMilestone) right).getItem();
        }
        return true;
    }
    public static boolean sameSelection(Milestone left, Milestone right) {
        return sameGoal(left, right);
    }
    public boolean replaceGoal(Milestone original, Milestone replacement) {
        return replaceGoal(original, replacement, getMetadata(original).getRecurring().getSchedule());
    }
    public boolean replaceGoal(Milestone original, Milestone replacement, RepeatSchedule schedule) {
        if (original == replacement) {
            return goals.contains(original);
        }
        int index = goals.indexOf(original);
        if (index < 0) {
            return false;
        }
        for (Milestone goal : goals) {
            if (goal != original && sameGoal(goal, replacement) && getMetadata(goal).getRecurring().getSchedule() == schedule) {
                throw new IllegalArgumentException("That tracker and schedule are already tracked. Edit the existing milestone instead.");
            }
        }
        MilestoneMetadata old = getMetadata(original);
        if (!sameGoal(original, replacement)) {
            archive(original);
        }
        MilestoneMetadata next = sameGoal(original, replacement) ? old : new MilestoneMetadata();
        if (sameGoal(original, replacement) && original instanceof SessionExperienceMilestone) {
            ((SessionExperienceMilestone) replacement).copyReadingsFrom((SessionExperienceMilestone) original);
        }
        next.setPinned(old.isPinned());
        attachCollectionData(replacement);
        goals.set(index, replacement);
        metadata.put(replacement, next);
        metadata.remove(original);
        touch();
        return true;
    }

    public void validateReferences() {
        Map<String, Milestone> byId = new HashMap<>();
        for (Milestone goal : goals) {
            if (byId.put(getMetadata(goal).getId(), goal) != null) {
                throw new IllegalArgumentException("Duplicate milestone metadata ID.");
            }
        }
        for (Milestone goal : goals) {
            if (goal instanceof LinkedMilestone) {
                for (String source : ((LinkedMilestone) goal).getSources()) {
                    if (byId.get(source) instanceof LinkedMilestone) {
                        throw new IllegalArgumentException("Linked milestones cannot reference other linked milestones.");
                    }
                }
            }
        }
    }

    public boolean remove(Milestone goal) {
        if (goals.contains(goal)) {
            archive(goal);
        }
        boolean removed = goals.remove(goal);
        if (removed) {
            touch();
        }
        return removed;
    }
    public int mergeBackup(GrindstoneProfile backup) {
        if (backup.hash != hash) {
            throw new IllegalArgumentException("Backup must be mapped to this account before merging.");
        }
        int added = 0;
        Map<String, String> mapping = new HashMap<>();
        for (Milestone goal : backup.getGoals()) {
            Milestone existing = findMatchingGoal(goal, backup.getMetadata(goal).getRecurring().getSchedule());
            mapping.put(backup.getMetadata(goal).getId(), existing == null ? backup.getMetadata(goal).getId() : getMetadata(existing).getId());
        }
        for (Milestone goal : backup.getGoals()) {
            if (goal instanceof LinkedMilestone && findMatchingGoal(goal) == null) {
                ((LinkedMilestone) goal).remapSources(mapping);
            }
            if (add(goal, backup.getMetadata(goal))) {
                added++;
            }
        }
        backup.collectionLogHistory.getSnapshot().forEach(collectionLogHistory::record);
        playerStorage.mergeSnapshots(backup.playerStorage);
        backup.getArchivedHistory().forEach(this::restoreArchive);
        setItemManager(itemManager);
        return added;
    }

    public List<Milestone> getGoals() {
        return Collections.unmodifiableList(goals);
    }

    public void replace(List<Milestone> goals) {
        this.goals.clear();
        this.goals.addAll(goals);
        this.goals.forEach(this::attachCollectionData);
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/19/2026
     */
    public static final class ArchivedHistory {
        private final String title;
        private final MilestoneMetadata metadata;
        private ArchivedHistory(String title, MilestoneMetadata metadata) {
            this.title = title;
            this.metadata = metadata;
        }
        public String getTitle() {
            return title;
        }
        public MilestoneMetadata getMetadata() {
            return metadata;
        }
    }
}

package com.grindstone.repository;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.grindstone.content.collectionlog.CollectionLogEntry;
import com.grindstone.content.milestone.ClientCompletionMilestone;
import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.impl.ChecklistMilestone;
import com.grindstone.content.milestone.impl.CustomMilestone;
import com.grindstone.content.milestone.impl.LinkedMilestone;
import com.grindstone.content.milestone.impl.TrackerMilestone;
import com.grindstone.content.milestone.impl.collectionlog.CollectionLogEntryMilestone;
import com.grindstone.content.milestone.impl.collectionlog.CollectionLogTabMilestone;
import com.grindstone.content.milestone.impl.experience.SessionExperienceMilestone;
import com.grindstone.content.milestone.impl.experience.SkillExperienceMilestone;
import com.grindstone.content.milestone.impl.item.PossessedItemMilestone;
import com.grindstone.content.milestone.impl.level.SkillLevelMilestone;
import com.grindstone.content.storage.PlayerStorageSnapshot;
import com.grindstone.content.storage.PlayerStorageSource;
import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
@lombok.extern.slf4j.Slf4j
@Singleton
public final class GrindstoneRepository {
    public static final int MAX_PROFILE_BYTES = 20_000_000;
    private final Gson gson;
    private final JsonObject metadataDefaults;
    private final JsonObject recurringDefaults;

    @Inject
    public GrindstoneRepository(Gson gson) {
        this.gson = gson;
        metadataDefaults = gson.toJsonTree(new MilestoneMetadata()).getAsJsonObject();
        metadataDefaults.remove("id");
        recurringDefaults = gson.toJsonTree(new RecurringMilestone()).getAsJsonObject();
    }

    public GrindstoneProfile load(Filepath directory, long hash) throws IOException {
        requireHash(hash);
        Filepath file = directory.joinSegment(hash + ".json");
        Filepath recovery = directory.joinSegment(hash + ".json.bak");
        if (!file.exists() && !recovery.exists()) {
            return new GrindstoneProfile(hash);
        }
        try {
            return readProfile(file, hash);
        } catch (IOException | RuntimeException failure) {
            if (!recovery.exists()) {
                throw new IOException("The saved profile could not be read. It has not been replaced.", failure);
            }
            GrindstoneProfile restored = readProfile(recovery, hash);
            log.warn("Recovered a Grindstone profile from its previous valid save");
            return restored;
        }
    }

    public GrindstoneProfile readProfile(Filepath file, long hash) throws IOException {
        return readProfile(readText(file, MAX_PROFILE_BYTES), hash);
    }

    public GrindstoneProfile readProfile(String text, long hash) throws IOException {
        requireHash(hash);
        JsonObject json = new JsonParser().parse(text).getAsJsonObject();
        if (!json.has("hash") || json.get("hash").getAsLong() != hash || !json.has("goals") || !json.get("goals").isJsonArray() || json.getAsJsonArray("goals").size() > 5000) {
            throw new IOException("This profile does not belong to the current account or has invalid milestone data.");
        }
        GrindstoneProfile profile = decode(json, true);
        if (profile.getGoals().size() != json.getAsJsonArray("goals").size()) {
            throw new IOException("The profile contains unsupported or invalid milestones. The original file has not been changed.");
        }
        return profile;
    }

    public String readText(Filepath file, int maximum) throws IOException {
        if (!file.isFile() || file.size() > maximum) {
            throw new IOException("The selected file is missing or exceeds the size limit.");
        }
        StringBuilder text = new StringBuilder();
        try (Reader reader = file.openReader()) {
            char[] buffer = new char[8192];
            int count;
            while ((count = reader.read(buffer)) != -1) {
                text.append(buffer, 0, count);
                if (text.length() > maximum) {
                    throw new IOException("The file exceeds the size limit.");
                }
            }
        }
        return text.toString();
    }

    public void save(Filepath directory, JsonObject snapshot) throws IOException {
        long hash = snapshot.get("hash").getAsLong();
        requireHash(hash);
        String text = snapshot.toString();
        if (text.length() > MAX_PROFILE_BYTES || text.getBytes(StandardCharsets.UTF_8).length > MAX_PROFILE_BYTES) {
            throw new IOException("The profile exceeds the save size limit. The previous save has not been changed.");
        }
        directory.createDirectories();
        Filepath destination = directory.joinSegment(hash + ".json");
        Filepath recovery = directory.joinSegment(hash + ".json.bak");
        Filepath temporary = directory.createTempFile("profile-", ".tmp");
        try {
            temporary.write(text);
            if (destination.exists()) {
                boolean valid = true;
                try {
                    readProfile(destination, hash);
                } catch (IOException | RuntimeException failure) {
                    valid = false;
                }
                if (valid) {
                    destination.copyTo(recovery, StandardCopyOption.REPLACE_EXISTING);
                } else {
                    destination.copyTo(directory.joinSegment(hash + ".corrupt-" + System.currentTimeMillis() + ".json"));
                }
            }
            try {
                temporary.moveTo(destination, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
            } catch (AtomicMoveNotSupportedException unsupported) {
                temporary.moveTo(destination, StandardCopyOption.REPLACE_EXISTING);
            }
        } finally {
            try {
                temporary.deleteIfExists();
            } catch (IOException cleanupFailure) {
                log.debug("Unable to remove an unused Grindstone save temporary file", cleanupFailure);
            }
        }
    }

    private static void requireHash(long hash) {
        if (hash == 0) {
            throw new IllegalArgumentException("A logged-in account is required.");
        }
    }

    public JsonObject toJson(GrindstoneProfile profile) {
        JsonObject json = new JsonObject();
        json.addProperty("hash", profile.getHash());

        JsonArray savedGoals = new JsonArray();

        for (Milestone goal : profile.getGoals()) {
            JsonObject savedGoal = new JsonObject();
            savedGoal.addProperty("type", SavedMilestoneTypes.nameOf(goal));
            JsonObject data = gson.toJsonTree(goal).getAsJsonObject();
            if (goal instanceof CollectionLogEntryMilestone && data.has("pageStruct")) {
                data.remove("entry");
            }
            savedGoal.add("data", data);
            JsonObject metadata = gson.toJsonTree(profile.getMetadata(goal)).getAsJsonObject();
            removeDefaults(metadata, metadataDefaults);
            if (metadata.has("recurring") && metadata.get("recurring").isJsonObject()) {
                JsonObject recurring = metadata.getAsJsonObject("recurring");
                removeDefaults(recurring, recurringDefaults);
                if (recurring.size() == 0) {
                    metadata.remove("recurring");
                }
            }
            savedGoal.add("metadata", metadata);
            savedGoals.add(savedGoal);
        }

        json.add("goals", savedGoals);
        if (!profile.getArchivedHistory().isEmpty()) {
            json.add("archivedHistory", gson.toJsonTree(profile.getArchivedHistory()));
        }
        JsonObject observed = new JsonObject();
        Map<Long, JsonArray> observationsByTime = new LinkedHashMap<>();
        new TreeMap<>(profile.getCollectionLogHistory().getSnapshot()).forEach((id, time) -> {
            observed.addProperty(id.toString(), time);
            JsonArray group = observationsByTime.computeIfAbsent(time, timestamp -> {
                JsonArray values = new JsonArray();
                values.add(timestamp);
                return values;
            });
            group.add(id);
        });
        if (observed.size() > 0) {
            JsonArray groups = new JsonArray();
            observationsByTime.values().forEach(groups::add);
            if (groups.toString().length() + 6 < observed.toString().length()) {
                json.add("collectionLogFirstSeenGroups", groups);
            } else {
                json.add("collectionLogFirstSeen", observed);
            }
        }
        if (profile.getCollectionLogHistory().getSnapshotAt() > 0) {
            json.addProperty("collectionLogSnapshotAt", profile.getCollectionLogHistory().getSnapshotAt());
            json.addProperty("collectionLogSnapshotCount", profile.getCollectionLogHistory().getSnapshotCount());
        }

        JsonObject storage = new JsonObject();
        JsonObject containers = new JsonObject();
        profile.getPlayerStorage().getContainerSnapshots().forEach((source, snapshot) -> containers.add(source.name(), gson.toJsonTree(snapshot)));
        if (containers.size() > 0) {
            storage.add("containers", containers);
        }
        if (!profile.getPlayerStorage().getVariableSnapshots().isEmpty()) {
            storage.add("variables", gson.toJsonTree(profile.getPlayerStorage().getVariableSnapshots()));
        }
        if (storage.size() > 0) {
            json.add("storageSnapshots", storage);
        }
        return json;
    }

    private static void removeDefaults(JsonObject saved, JsonObject defaults) {
        for (Map.Entry<String, JsonElement> entry : defaults.entrySet()) {
            if (entry.getValue().equals(saved.get(entry.getKey()))) {
                saved.remove(entry.getKey());
            }
        }
    }

    private void restoreStorageSnapshots(GrindstoneProfile profile, JsonObject json, boolean strict) {
        if (!json.has("storageSnapshots")) {
            return;
        }
        try {
            JsonObject storage = json.getAsJsonObject("storageSnapshots");
            for (String group : new String[]{"containers", "variables"}) {
                if (!storage.has(group)) {
                    continue;
                }
                for (Map.Entry<String, JsonElement> entry : storage.getAsJsonObject(group).entrySet()) {
                    try {
                        PlayerStorageSnapshot snapshot = gson.fromJson(entry.getValue(), PlayerStorageSnapshot.class);
                        if ("containers".equals(group)) {
                            profile.getPlayerStorage().restoreContainerSnapshot(PlayerStorageSource.valueOf(entry.getKey()), snapshot);
                        } else {
                            profile.getPlayerStorage().restoreVariableSnapshot(entry.getKey(), snapshot);
                        }
                    } catch (RuntimeException exception) {
                        if (strict) {
                            throw exception;
                        }
                        log.debug("Ignoring invalid storage snapshot {}", entry.getKey(), exception);
                    }
                }
            }
        } catch (RuntimeException exception) {
            if (strict) {
                throw new IllegalArgumentException("Invalid storage snapshots", exception);
            }
            log.debug("Ignoring invalid storage snapshots", exception);
        }
    }

    public GrindstoneProfile fromJson(JsonObject json) {
        return decode(json, false);
    }

    private GrindstoneProfile decode(JsonObject json, boolean strict) {
        long hash = json.get("hash").getAsLong();
        GrindstoneProfile profile = new GrindstoneProfile(hash);
        restoreStorageSnapshots(profile, json, strict);
        if (json.has("collectionLogFirstSeen") && json.get("collectionLogFirstSeen").isJsonObject()) {
            for (Map.Entry<String, JsonElement> observation : json.getAsJsonObject("collectionLogFirstSeen").entrySet()) {
                try {
                    profile.getCollectionLogHistory().record(Integer.parseInt(observation.getKey()), observation.getValue().getAsLong());
                } catch (RuntimeException exception) {
                    if (strict) {
                        throw new IllegalArgumentException("Invalid collection-log observation", exception);
                    }
                    log.debug("Skipping an invalid collection-log observation", exception);
                }
            }
        }
        if (json.has("collectionLogFirstSeenGroups")) {
            for (JsonElement saved : json.getAsJsonArray("collectionLogFirstSeenGroups")) {
                try {
                    JsonArray group = saved.getAsJsonArray();
                    if (group.size() < 2 || group.size() > 10001) {
                        throw new IllegalArgumentException("Invalid collection-log observation group");
                    }
                    long timestamp = group.get(0).getAsLong();
                    for (int i = 1; i < group.size(); i++) {
                        profile.getCollectionLogHistory().record(group.get(i).getAsInt(), timestamp);
                    }
                } catch (RuntimeException exception) {
                    if (strict) {
                        throw new IllegalArgumentException("Invalid collection-log observation group", exception);
                    }
                    log.debug("Skipping an invalid collection-log observation group", exception);
                }
            }
        }

        if (json.has("collectionLogSnapshotAt")) {
            try {
                long snapshotAt = json.get("collectionLogSnapshotAt").getAsLong();
                if (snapshotAt != 0) {
                    profile.getCollectionLogHistory().restoreSnapshot(snapshotAt, json.get("collectionLogSnapshotCount").getAsInt());
                }
            } catch (RuntimeException exception) {
                if (strict) {
                    throw new IllegalArgumentException("Invalid collection-log snapshot", exception);
                }
                log.debug("Ignoring an invalid collection-log snapshot", exception);
            }
        }

        if (!json.has("goals") || !json.get("goals").isJsonArray()) {
            return profile;
        }

        List<Milestone> goals = new ArrayList<>();
        JsonArray savedGoals = json.getAsJsonArray("goals");

        for (JsonElement element : savedGoals) {
            try {
                JsonObject savedGoal = element.getAsJsonObject();
                JsonElement data = savedGoal.get("data");
                Class<? extends Milestone> type = SavedMilestoneTypes.fromTag(savedGoal);
                if (type == null || data == null || !data.isJsonObject()) {
                    continue;
                }
                Milestone goal;
                if (type == CollectionLogTabMilestone.class) {
                    JsonObject tab = data.getAsJsonObject();
                    goal = new CollectionLogTabMilestone(tab.get("tabStruct").getAsInt(), tab.get("tabName").getAsString());
                } else if (type == CollectionLogEntryMilestone.class) {
                    JsonObject page = data.getAsJsonObject();
                    if (page.has("pageStruct")) {
                        goal = new CollectionLogEntryMilestone(null, page.get("pageStruct").getAsInt(), page.get("pageName").getAsString());
                    } else {
                        JsonElement entryElement = data.getAsJsonObject().get("entry");
                        if (entryElement == null || entryElement.isJsonNull()) {
                            continue;
                        }
                        CollectionLogEntry entry = gson.fromJson(entryElement, CollectionLogEntry.class);
                        if (entry == null) {
                            continue;
                        }
                        goal = new CollectionLogEntryMilestone(null, entry);
                    }
                } else if (type == CustomMilestone.class) {
                    CustomMilestone saved = gson.fromJson(data, CustomMilestone.class);
                    goal = new CustomMilestone(saved.getId(), saved.getTitle(null), saved.getDescription(), saved.getCategory(), saved.getProgressCurrent(), saved.getProgressMaximum());
                } else if (type == PossessedItemMilestone.class) {
                    PossessedItemMilestone saved = gson.fromJson(data, PossessedItemMilestone.class);
                    goal = new PossessedItemMilestone(saved.getItem(), saved.getAmount());
                } else {
                    goal = gson.fromJson(data, type);
                }

                if (goal != null) {
                    if (goal instanceof ChecklistMilestone) {
                        ((ChecklistMilestone) goal).validate();
                    }
                    if (goal instanceof SessionExperienceMilestone) {
                        ((SessionExperienceMilestone) goal).validate();
                    }
                    if (goal instanceof LinkedMilestone) {
                        ((LinkedMilestone) goal).validate();
                    }
                    if (goal instanceof ClientCompletionMilestone) {
                        ((ClientCompletionMilestone) goal).selectionKey();
                    }
                    if (goal instanceof SkillLevelMilestone && ((SkillLevelMilestone) goal).getSkill() == null || goal instanceof SkillExperienceMilestone && ((SkillExperienceMilestone) goal).getSkill() == null || goal instanceof TrackerMilestone && ((TrackerMilestone) goal).getTracker() == null) {
                        continue;
                    }
                    if (goal.supportsTarget()) {
                        goal.setTarget(goal.getProgressMaximum());
                    }
                    goals.add(goal);
                    if (savedGoal.has("metadata")) {
                        try {
                            profile.restoreMetadata(goal, gson.fromJson(savedGoal.get("metadata"), MilestoneMetadata.class));
                        } catch (RuntimeException exception) {
                            if (strict) {
                                throw new IllegalArgumentException("Invalid milestone metadata", exception);
                            }
                            log.debug("Skipping invalid milestone metadata", exception);
                        }
                    }
                }
            } catch (RuntimeException exception) {
                if (strict) {
                    throw new IllegalArgumentException("Invalid saved milestone", exception);
                }
                log.debug("Skipping an invalid saved Grindstone milestone", exception);
            }
        }

        profile.replace(goals);
        if (json.has("archivedHistory") && json.get("archivedHistory").isJsonArray()) {
            if (json.getAsJsonArray("archivedHistory").size() > 500) {
                throw new IllegalArgumentException("Too many archived milestone histories");
            }
            for (JsonElement saved : json.getAsJsonArray("archivedHistory")) {
                try {
                    profile.restoreArchive(gson.fromJson(saved, GrindstoneProfile.ArchivedHistory.class));
                } catch (RuntimeException exception) {
                    if (strict) {
                        throw new IllegalArgumentException("Invalid archived milestone history", exception);
                    }
                    log.debug("Skipping invalid archived milestone history", exception);
                }
            }
        }
        if (strict) {
            profile.validateReferences();
        }
        return profile;
    }

    public String exportBackup(GrindstoneProfile profile) {
        JsonObject snapshot = toJson(profile);
        snapshot.addProperty("backupVersion", 1);
        return snapshot.toString();
    }
    public GrindstoneProfile importBackup(String text, long targetHash) {
        if (text == null || text.length() > 5_000_000) {
            throw new IllegalArgumentException("Backup must be smaller than 5 MB.");
        }
        JsonObject json = new JsonParser().parse(text).getAsJsonObject();
        if (!json.has("hash") || !json.has("goals") || !json.get("goals").isJsonArray() || json.getAsJsonArray("goals").size() > 5000) {
            throw new IllegalArgumentException("Not a valid Grindstone profile backup.");
        }
        if (json.has("backupVersion") && json.get("backupVersion").getAsInt() != 1) {
            throw new IllegalArgumentException("Unsupported backup version.");
        }
        boolean sameAccount = json.get("hash").getAsLong() == targetHash;
        json.addProperty("hash", targetHash);
        if (!sameAccount) {
            json.remove("archivedHistory");
            json.remove("collectionLogFirstSeen");
            json.remove("collectionLogFirstSeenGroups");
            json.remove("storageSnapshots");
            json.remove("collectionLogSnapshotAt");
            json.remove("collectionLogSnapshotCount");
            for (JsonElement element : json.getAsJsonArray("goals")) {
                JsonObject saved = element.getAsJsonObject();
                if (saved.has("metadata") && saved.get("metadata").isJsonObject()) {
                    JsonObject metadata = saved.getAsJsonObject("metadata");
                    metadata.addProperty("lastObservedAt", 0);
                    metadata.addProperty("hasLastReading", false);
                    metadata.addProperty("lastObservedCurrent", 0);
                    metadata.addProperty("lastObservedTarget", 0);
                    metadata.add("completions", new JsonArray());
                    if (metadata.has("recurring") && metadata.get("recurring").isJsonObject()) {
                        JsonObject recurring = metadata.getAsJsonObject("recurring");
                        for (String key : new String[]{"start", "baselineAt", "lastValue", "progress", "completedAt", "lastObservedAt"}) {
                            recurring.addProperty(key, 0);
                        }
                        recurring.add("history", new JsonArray());
                    }
                }
                if (SavedMilestoneTypes.fromTag(saved) == CustomMilestone.class) {
                    saved.getAsJsonObject("data").addProperty("current", 0);
                }
                if (SavedMilestoneTypes.fromTag(saved) == ChecklistMilestone.class) {
                    JsonObject data = saved.getAsJsonObject("data");
                    JsonArray cleared = new JsonArray();
                    for (JsonElement ignored : data.getAsJsonArray("checked")) {
                        cleared.add(false);
                    }
                    data.add("checked", cleared);
                }
                if (SavedMilestoneTypes.fromTag(saved) == LinkedMilestone.class) {
                    JsonObject data = saved.getAsJsonObject("data");
                    if (data.has("achieved")) {
                        JsonArray cleared = new JsonArray();
                        for (JsonElement ignored : data.getAsJsonArray("achieved")) {
                            cleared.add(false);
                        }
                        data.add("achieved", cleared);
                    }
                    data.add("completedThrough", new JsonObject());
                    data.addProperty("completedPeriods", 0);
                }
            }
        }
        GrindstoneProfile restored = decode(json, true);
        if (restored.getGoals().size() != json.getAsJsonArray("goals").size()) {
            throw new IllegalArgumentException("Backup contains invalid or unsupported milestones. No milestones were imported.");
        }
        return restored;
    }
}

package com.grindstone.repository;

import com.grindstone.content.milestone.Milestone;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.function.Function;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class HistoryRecord {
    public final String goalId;
    public final String title;
    public final RepeatSchedule schedule;
    public final long start;
    public final long end;
    public final Long progress;
    public final long target;
    public final String outcome;
    public final long baseline;
    public final long observed;
    public final long completed;
    public final boolean lifetime;
    public HistoryRecord(String goalId, String title, RepeatSchedule schedule, long start, long end, Long progress, long target, String outcome, long baseline, long observed, long completed, boolean lifetime) {
        this.goalId = goalId;
        this.title = title;
        this.schedule = schedule;
        this.start = start;
        this.end = end;
        this.progress = progress;
        this.target = target;
        this.outcome = outcome;
        this.baseline = baseline;
        this.observed = observed;
        this.completed = completed;
        this.lifetime = lifetime;
    }
    public boolean matches(String query, RepeatSchedule repeat, long from, long to) {
        return (repeat == null || schedule == repeat) && (query == null || (title + " " + outcome).toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT).trim())) && (end == 0 || end > from) && start < to;
    }
    public static List<HistoryRecord> createSnapshot(GrindstoneProfile profile, Function<Milestone, String> title) {
        List<HistoryRecord> records = new ArrayList<>();
        for (Milestone goal : profile.getGoals()) {
            MilestoneMetadata metadata = profile.getMetadata(goal);
            String name = title.apply(goal);
            append(records, metadata, name, metadata.getId());
        }
        for (GrindstoneProfile.ArchivedHistory archived : profile.getArchivedHistory()) {
            append(records, archived.getMetadata(), archived.getTitle() + " (archived)", "");
        }
        records.sort(Comparator.comparingLong((HistoryRecord value) -> value.start).reversed());
        return records;
    }
    private static void append(List<HistoryRecord> records, MilestoneMetadata metadata, String name, String id) {
        RecurringMilestone recurring = metadata.getRecurring();
        if (recurring.isActive()) {
            long start = recurring.getStart();
            records.add(new HistoryRecord(id, name, recurring.getSchedule(), start, recurring.getBaselineAt() == 0 ? 0 : recurring.getSchedule().getNextReset(start), recurring.getBaselineAt() == 0 ? null : recurring.getProgress(), recurring.getTarget(), recurring.getBaselineAt() == 0 ? "Waiting for data" : recurring.getCompletedAt() > 0 ? "Completed · current period" : "Current period", recurring.getBaselineAt(), recurring.getLastObservedAt(), recurring.getCompletedAt(), false));
        }
        for (RecurringMilestone.Period period : recurring.getHistory()) {
            records.add(new HistoryRecord(id, name, period.getSchedule(), period.getStart(), period.getEnd(), period.getBaselineAt() == 0 ? null : period.getProgress(), period.getTarget(), period.getOutcome(), period.getBaselineAt(), period.getLastObservedAt(), period.getCompletedAt(), false));
        }
        for (MilestoneMetadata.Completion completion : metadata.getCompletions()) {
            records.add(new HistoryRecord(id, completion.getTitle(), RepeatSchedule.NONE, completion.getObservedAt(), completion.getObservedAt() + 1, completion.getTarget(), completion.getTarget(), "Lifetime target reached", 0, completion.getObservedAt(), completion.getObservedAt(), true));
        }
    }
}

package com.grindstone.repository;
import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.MilestoneCategory;
import com.grindstone.content.milestone.MilestoneStatus;
import com.grindstone.content.milestone.ManualMilestone;
import com.grindstone.content.milestone.impl.LinkedMilestone;
import com.grindstone.content.milestone.impl.experience.SessionExperienceMilestone;
import com.grindstone.content.milestone.impl.item.PossessedItemMilestone;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.UUID;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.Setter;
/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
public final class MilestoneMetadata {
    @Getter
    private final String id;
    @Getter
    @Setter
    private boolean pinned;
    private Boolean collapsed;
    @Getter
    private long deadlineAt;
    @Getter
    private boolean deadlineReminder;
    @Getter
    private long lastObservedAt;
    private boolean hasLastReading;
    private long lastObservedCurrent;
    private long lastObservedTarget;
    private transient boolean catchUpPending;
    @Getter
    private transient String catchUpText;

    public void beginCatchUp() {
        catchUpPending = hasLastReading;
        catchUpText = null;
    }

    public void observeReading(Milestone goal, String title, long now) {
        if (now <= 0 || goal instanceof ManualMilestone || goal instanceof LinkedMilestone || goal instanceof SessionExperienceMilestone || goal instanceof PossessedItemMilestone || goal.getProgressMaximum() <= 0) {
            return;
        }
        long current = Math.max(0, goal.getProgressCurrent());
        long target = goal.getProgressMaximum();
        if (catchUpPending && lastObservedTarget == target) {
            // Some activity counters load only after their native interface is opened.
            if (current < lastObservedCurrent) {
                return;
            }
            if (current > lastObservedCurrent) {
                catchUpText = String.format(Locale.ROOT, "%s: +%,d (%,d to %,d)%s", title, current - lastObservedCurrent, lastObservedCurrent, current, lastObservedCurrent < target && current >= target ? " - target reached" : "");
            }
        }
        catchUpPending = false;
        hasLastReading = true;
        lastObservedCurrent = current;
        lastObservedTarget = target;
    }
    @Getter
    @Setter
    private MilestoneCategory displayCategory;
    private RecurringMilestone recurring;
    public RecurringMilestone getRecurring() {
        if (recurring == null) {
            recurring = new RecurringMilestone();
        }
        return recurring;
    }
    public boolean isCollapsed(boolean defaultValue) {
        return collapsed == null ? defaultValue : collapsed;
    }
    public void setCollapsed(boolean collapsed) {
        this.collapsed = collapsed;
    }
    public void setDeadline(long deadlineAt, boolean reminder) {
        if (deadlineAt < 0 || deadlineAt > 253_370_764_800_000L) {
            throw new IllegalArgumentException("Invalid personal deadline.");
        }
        this.deadlineAt = deadlineAt;
        deadlineReminder = deadlineAt != 0 && reminder;
    }
    public String getDeadlineText(long now) {
        if (deadlineAt == 0) {
            return "";
        }
        String date = Instant.ofEpochMilli(deadlineAt - 1).atZone(ZoneOffset.UTC).toLocalDate().toString();
        return (now >= deadlineAt ? "Past due · " : "Due · ") + date + " UTC";
    }
    private final List<Completion> completions = new ArrayList<>();
    public MilestoneMetadata() {
        id = UUID.randomUUID().toString();
    }
    private MilestoneMetadata(MilestoneMetadata source) {
        id = source.id;
        pinned = source.pinned;
        collapsed = source.collapsed;
        deadlineAt = source.deadlineAt;
        deadlineReminder = source.deadlineReminder;
        lastObservedAt = source.lastObservedAt;
        hasLastReading = source.hasLastReading;
        lastObservedCurrent = source.lastObservedCurrent;
        lastObservedTarget = source.lastObservedTarget;
        catchUpPending = source.catchUpPending;
        catchUpText = source.catchUpText;
        displayCategory = source.displayCategory;
        recurring = source.recurring == null ? null : source.recurring.copy();
        completions.addAll(source.completions);
    }
    public MilestoneMetadata copy() {
        return new MilestoneMetadata(this);
    }
    public List<Completion> getCompletions() {
        return Collections.unmodifiableList(completions);
    }
    public boolean observe(Milestone goal, String title, long now) {
        observeReading(goal, title, now);
        if (now > 0) {
            lastObservedAt = Math.max(lastObservedAt, now);
        }
        long target = goal.getProgressMaximum();
        if (goal.getStatus() != MilestoneStatus.COMPLETE || target <= 0 || now <= 0 || completions.stream().anyMatch(event -> event.target == target)) {
            return false;
        }
        completions.add(new Completion(title, target, now));
        return true;
    }
    public static MilestoneMetadata validated(MilestoneMetadata saved) {
        UUID.fromString(saved.id);
        saved.setDeadline(saved.deadlineAt, saved.deadlineReminder);
        if (saved.lastObservedAt < 0 || saved.lastObservedCurrent < 0 || saved.lastObservedTarget < 0 || saved.hasLastReading && saved.lastObservedTarget == 0) {
            throw new IllegalArgumentException("Invalid last observation.");
        }
        if (saved.recurring != null) {
            saved.recurring.validate();
        }
        if (saved.completions == null || saved.completions.size() > 2000) {
            throw new IllegalArgumentException("Invalid completion history");
        }
        for (Completion event : saved.completions) {
            if (event == null || event.title == null || event.title.length() > 300 || event.target <= 0 || event.observedAt <= 0) {
                throw new IllegalArgumentException("Invalid completion observation");
            }
        }
        return saved;
    }
    public String getHistoryText() {
        if (completions.isEmpty()) {
            return "No completed targets observed yet.";
        }
        StringBuilder text = new StringBuilder("First observed completed (not the historical achievement date):\n\n");
        for (Completion event : completions) {
            text.append(event.title).append(" — target ").append(String.format(Locale.ROOT, "%,d", event.target)).append(" — ").append(Instant.ofEpochMilli(event.observedAt)).append('\n');
        }
        return text.toString();
    }
    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/18/2026
     */
    @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
    public static final class Completion {
        @Getter
        private final String title;
        @Getter
        private final long target;
        @Getter
        private final long observedAt;
    }
}

package com.grindstone.repository;

import lombok.Getter;
import java.util.function.BooleanSupplier;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class MilestoneUndo {
    private GrindstoneProfile profile;
    private long revision;
    private Runnable action;
    private BooleanSupplier allowed;
    @Getter
    private String label;
    public void record(GrindstoneProfile profile, String label, Runnable action, BooleanSupplier allowed) {
        this.profile = profile;
        this.revision = profile.getRevision();
        this.label = label;
        this.action = action;
        this.allowed = allowed;
    }
    public void clear() {
        profile = null;
        action = null;
        allowed = null;
        label = null;
    }
    public boolean undo(GrindstoneProfile active) {
        boolean valid = active != null && active == profile && active.getRevision() == revision && action != null && allowed.getAsBoolean();
        Runnable saved = action;
        clear();
        if (valid) {
            try {
                saved.run();
            } catch (IllegalStateException exception) {
                return false;
            }
        }
        return valid;
    }
}

package com.grindstone.repository;

import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.Callable;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executor;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Filepath;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
@Singleton
public final class ProfilePersistence {
    public static final int MAX_SYNC_CHARACTERS = 262000;
    private static final String STORAGE_GROUP = "grindstoneData";
    private final GrindstoneRepository repository;
    private final Executor executor;
    private final SyncedProfiles syncedProfiles;
    private final Map<Long, String> profileKeys = new ConcurrentHashMap<>();
    private CompletableFuture<Void> tail = CompletableFuture.completedFuture(null);
    private Directory directory;

    @Inject
    public ProfilePersistence(GrindstoneRepository repository, ScheduledExecutorService executor, ConfigManager configManager) {
        this(repository, executor, new SyncedProfiles() {
            @Override
            public String prepareProfile() {
                if (configManager.getRSProfileKey() == null) {
                    configManager.setRSProfileConfiguration(STORAGE_GROUP, "version", 1);
                }
                return configManager.getRSProfileKey();
            }

            @Override
            public String read(String profileKey) {
                return configManager.getConfiguration(STORAGE_GROUP, profileKey, "profile");
            }

            @Override
            public void write(String profileKey, String text) {
                configManager.setConfiguration(STORAGE_GROUP, profileKey, "profile", text);
            }

            @Override
            public void flush() {
                configManager.sendConfig();
            }
        });
    }

    ProfilePersistence(GrindstoneRepository repository, Executor executor) {
        this(repository, executor, null);
    }

    ProfilePersistence(GrindstoneRepository repository, Executor executor, SyncedProfiles syncedProfiles) {
        this.repository = repository;
        this.executor = executor;
        this.syncedProfiles = syncedProfiles;
    }

    public synchronized void configure(Directory directory) {
        this.directory = directory;
    }

    public CompletableFuture<GrindstoneProfile> load(long hash) {
        Directory root = getDirectory();
        String profileKey = syncedProfiles == null ? null : syncedProfiles.prepareProfile();
        if (profileKey != null) {
            profileKeys.put(hash, profileKey);
        }
        return enqueue(() -> {
            Filepath profiles = root.get().joinSegment("profiles");
            if (syncedProfiles != null) {
                requireProfileKey(profileKey);
                if (profiles.joinSegment(hash + ".sync-pending").exists()) {
                    if (!profiles.joinSegment(hash + ".json").exists() && !profiles.joinSegment(hash + ".json.bak").exists()) {
                        throw new IOException("The pending local profile is missing. Synced data has not been changed.");
                    }
                    return repository.load(profiles, hash);
                }
                String saved = syncedProfiles.read(profileKey);
                if (saved != null) {
                    if (saved.length() > MAX_SYNC_CHARACTERS) {
                        throw new IOException("The synced profile exceeds RuneLite's storage limit.");
                    }
                    return repository.readProfile(saved, hash);
                }
            }
            GrindstoneProfile loaded = repository.load(profiles, hash);
            if (syncedProfiles != null) {
                String text = repository.toJson(loaded).toString();
                if (text.length() <= MAX_SYNC_CHARACTERS) {
                    syncedProfiles.write(profileKey, text);
                }
            }
            return loaded;
        });
    }

    public CompletableFuture<Void> save(JsonObject snapshot) {
        Directory root = getDirectory();
        String profileKey = profileKeys.get(snapshot.get("hash").getAsLong());
        return enqueue(() -> {
            Filepath profiles = root.get().joinSegment("profiles");
            Filepath pending = profiles.joinSegment(snapshot.get("hash").getAsLong() + ".sync-pending");
            String text = snapshot.toString();
            repository.save(profiles, snapshot);
            if (syncedProfiles != null) {
                pending.write("1");
                requireProfileKey(profileKey);
                if (text.length() > MAX_SYNC_CHARACTERS) {
                    throw new SyncLimitException();
                }
                syncedProfiles.write(profileKey, text);
                pending.deleteIfExists();
            }
            return null;
        });
    }

    private static void requireProfileKey(String profileKey) throws IOException {
        if (profileKey == null) {
            throw new IOException("RuneLite's character profile is not ready. The local save has been kept.");
        }
    }

    public CompletableFuture<Void> flush() {
        return enqueue(() -> null);
    }

    public CompletableFuture<Void> sync() {
        return enqueue(() -> {
            if (syncedProfiles != null) {
                syncedProfiles.flush();
            }
            return null;
        });
    }

    public synchronized <T> CompletableFuture<T> enqueue(Callable<T> operation) {
        CompletableFuture<T> queued = tail.handle((ignored, failure) -> null).thenApplyAsync(ignored -> {
            if (SwingUtilities.isEventDispatchThread()) {
                throw new IllegalStateException("Profile disk work must not run on the UI thread.");
            }
            try {
                return operation.call();
            } catch (Exception failure) {
                throw new CompletionException(failure);
            }
        }, executor);
        tail = queued.handle((ignored, failure) -> null);
        return queued.thenApply(value -> value);
    }

    private synchronized Directory getDirectory() {
        if (directory == null) {
            throw new IllegalStateException("Profile storage is not configured.");
        }
        return directory;
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/19/2026
     */
    @FunctionalInterface
    public interface Directory {
        Filepath get() throws IOException;
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/21/2026
     */
    interface SyncedProfiles {
        String prepareProfile();

        String read(String profileKey);

        void write(String profileKey, String text);

        default void flush() {
        }
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/21/2026
     */
    public static final class SyncLimitException extends IOException {
        private SyncLimitException() {
            super("Profile exceeds RuneLite's 262,000-character sync limit. A local recovery copy was saved.");
        }
    }
}

package com.grindstone.repository;

import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.MilestoneStatus;
import com.grindstone.content.milestone.ManualMilestone;
import com.grindstone.content.milestone.impl.TrackerMilestone;
import com.grindstone.content.milestone.impl.experience.SkillExperienceMilestone;
import com.grindstone.content.milestone.impl.experience.TotalExperienceMilestone;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class RecurringMilestone {
    @Getter
    private RepeatSchedule schedule = RepeatSchedule.NONE;
    @Getter
    private long target = 1;
    @Getter
    private long start;
    @Getter
    private long baselineAt;
    private long lastValue;
    @Getter
    private long progress;
    @Getter
    private long completedAt;
    @Getter
    private long lastObservedAt;
    private final List<Period> history = new ArrayList<>();
    public RecurringMilestone copy() {
        RecurringMilestone copy = new RecurringMilestone();
        copy.schedule = schedule;
        copy.target = target;
        copy.start = start;
        copy.baselineAt = baselineAt;
        copy.lastValue = lastValue;
        copy.progress = progress;
        copy.completedAt = completedAt;
        copy.lastObservedAt = lastObservedAt;
        copy.history.addAll(history);
        return copy;
    }

    public static boolean supports(Milestone goal) {
        return goal instanceof ManualMilestone || goal instanceof TrackerMilestone || goal instanceof SkillExperienceMilestone || goal instanceof TotalExperienceMilestone;
    }
    public List<Period> getHistory() {
        return Collections.unmodifiableList(history);
    }
    public boolean isActive() {
        return schedule != RepeatSchedule.NONE;
    }
    public void stop(long now, String outcome) {
        if (isActive() && baselineAt > 0) {
            archive(now, outcome);
        }
        schedule = RepeatSchedule.NONE;
        start = 0;
        baselineAt = 0;
        progress = 0;
        completedAt = 0;
        lastObservedAt = 0;
    }
    public void restart(long now) {
        if (!isActive()) {
            throw new IllegalStateException("Only routines have periods.");
        }
        if (baselineAt > 0) {
            archive(now, "Period restarted · last observed");
        }
        start = 0;
        baselineAt = 0;
        progress = 0;
        completedAt = 0;
        lastObservedAt = 0;
    }
    public MilestoneStatus getStatus() {
        return progress >= target ? MilestoneStatus.COMPLETE : progress > 0 ? MilestoneStatus.IN_PROGRESS : MilestoneStatus.NOT_STARTED;
    }

    public void configure(RepeatSchedule schedule, long target, long now) {
        if (schedule == null || target < 1 || target > Integer.MAX_VALUE || now <= 0) {
            throw new IllegalArgumentException("Choose a repeat schedule and a target from 1 to 2,147,483,647.");
        }
        if (this.schedule == schedule && this.target == target) {
            return;
        }
        if (isActive() && baselineAt > 0) {
            archive(now, "Schedule changed");
        }
        this.schedule = schedule;
        this.target = target;
        start = 0;
        baselineAt = 0;
        progress = 0;
        completedAt = 0;
        lastObservedAt = 0;
    }

    public void observe(Milestone goal, long now) {
        if (!isActive() || !supports(goal) || now <= 0 || now < lastObservedAt) {
            return;
        }
        long periodStart = schedule.getPeriodStart(now);
        if (baselineAt > 0 && periodStart > start) {
            long previousEnd = schedule.getNextReset(start);
            archive(previousEnd, completedAt > 0 ? "Completed" : "Incomplete · last observed");
            if (periodStart > previousEnd) {
                append(new Period(schedule, previousEnd, periodStart, 0, target, 0, 0, 0, "Not observed"));
            }
            baselineAt = 0;
            if (goal instanceof ManualMilestone) {
                ((ManualMilestone) goal).resetProgress();
            }
        }
        long value = Math.max(0, goal.getProgressCurrent());
        if (baselineAt == 0) {
            start = periodStart;
            baselineAt = now;
            progress = 0;
            completedAt = 0;
            lastValue = value;
        }
        if (goal instanceof ManualMilestone) {
            progress = value;
        } else if (value >= lastValue) {
            progress = Math.min(Long.MAX_VALUE - (value - lastValue), progress) + (value - lastValue);
        }
        lastValue = value;
        lastObservedAt = now;
        if (progress >= target && completedAt == 0) {
            completedAt = now;
        }
    }

    private void archive(long end, String outcome) {
        append(new Period(schedule, start, Math.max(start + 1, end), progress, target, baselineAt, lastObservedAt, completedAt, outcome));
    }
    private void append(Period period) {
        history.add(period);
        if (history.size() > 500) {
            history.remove(0);
        }
    }

    public void validate() {
        if (schedule == null || target < 1 || target > Integer.MAX_VALUE || start < 0 || baselineAt < 0 || lastValue < 0 || progress < 0 || completedAt < 0 || lastObservedAt < 0 || history == null || history.size() > 500) {
            throw new IllegalArgumentException("Invalid routine");
        }
        for (Period period : history) {
            if (period == null || period.schedule == null || period.start < 0 || period.end <= period.start || period.progress < 0 || period.target < 1 || period.baselineAt < 0 || period.lastObservedAt < 0 || period.completedAt < 0 || period.outcome == null || period.outcome.length() > 100) {
                throw new IllegalArgumentException("Invalid period history");
            }
        }
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/19/2026
     */
    @RequiredArgsConstructor(access = AccessLevel.PRIVATE)
    public static final class Period {
        @Getter
        private final RepeatSchedule schedule;
        @Getter
        private final long start;
        @Getter
        private final long end;
        @Getter
        private final long progress;
        @Getter
        private final long target;
        @Getter
        private final long baselineAt;
        @Getter
        private final long lastObservedAt;
        @Getter
        private final long completedAt;
        @Getter
        private final String outcome;
    }
}

package com.grindstone.repository;

import java.time.DayOfWeek;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.time.temporal.TemporalAdjusters;
import java.util.Locale;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public enum RepeatSchedule {
    NONE,
    DAILY,
    WEEKLY,
    MONTHLY;

    public long getPeriodStart(long now) {
        LocalDate date = Instant.ofEpochMilli(now).atZone(ZoneOffset.UTC).toLocalDate();
        if (this == WEEKLY) {
            date = date.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));
        }
        if (this == MONTHLY) {
            date = date.withDayOfMonth(1);
        }
        return date.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
    }

    public long getNextReset(long start) {
        LocalDate date = Instant.ofEpochMilli(start).atZone(ZoneOffset.UTC).toLocalDate();
        date = this == MONTHLY ? date.plusMonths(1) : this == WEEKLY ? date.plusWeeks(1) : date.plusDays(1);
        return date.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();
    }

    @Override
    public String toString() {
        return this == NONE ? "One-time" : name().charAt(0) + name().substring(1).toLowerCase(Locale.ROOT);
    }
}

