public final class MilestoneCategorySectionComponent extends JPanel {
    private static final int HEADER_HEIGHT = 38;

    private final JPanel header = new JPanel(new BorderLayout(8, 0));
    @Getter
    private final JPanel content = new JPanel();
    private final JLabel iconLabel = new JLabel();
    private final JLabel titleLabel = new JLabel();
    private final JLabel countLabel = new JLabel();
    private final JLabel toggleLabel = new JLabel();
    @Getter
    private boolean expanded = true;

    public MilestoneCategorySectionComponent(String title, Icon icon) {
        setLayout(new BorderLayout());
        setOpaque(true);
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(BorderFactory.createCompoundBorder( BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 1), BorderFactory.createEmptyBorder(0, 0, 0, 0) ));

