        progressBar.setBorderPainted(false);
        progressBar.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
        progressBar.setPreferredSize(new Dimension(100, 9));
        progressBar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 9));

        progressLabel.setForeground(MUTED_COLOR);
        progressLabel.setFont(UiTypography.BODY);

        footer.setOpaque(false);
        footer.setLayout(new BorderLayout(0, 4));
        footer.add(progressBar, BorderLayout.CENTER);
        JPanel bottom = new JPanel(new BorderLayout(0, 6));
        bottom.setOpaque(false);
        bottom.add(progressLabel, BorderLayout.NORTH);
        bottom.add(manualControls, BorderLayout.SOUTH);
        manualControls.setVisible(false);
        footer.add(bottom, BorderLayout.SOUTH);
        statusLabel.setFont(UiTypography.BODY);
        footer.add(statusLabel, BorderLayout.NORTH);

        add(header, BorderLayout.NORTH);
        add(content, BorderLayout.CENTER);
        add(footer, BorderLayout.SOUTH);

        refreshLayout();
    }


    public void addDetail(JComponent detail) {
        content.add(detail);
        updateProgress();
    }

    public void setRequiredQuantity(long quantity) {
        requiredQuantityLabel.setText(String.format(Locale.ROOT, "Required: %,d", Math.max(0, quantity)));
        requiredQuantityLabel.setToolTipText("Target item quantity, not the amount currently owned. " + requiredQuantityLabel.getText());
        requiredQuantityLabel.setVisible(quantity > 0);
        revalidate();
        repaint();
    }
    public void setTrackingNote(String text) {
        trackingNoteLabel.setText(text);
        trackingNoteLabel.setToolTipText("A snapshot is the last known client data, not a guarantee that every storage location is loaded or current.");
        trackingNoteLabel.setVisible(text != null && !text.isEmpty());
        revalidate();
    }
    public void setAchievementNote(String text) {
        achievementNoteLabel.setText(text);
        achievementNoteLabel.setToolTipText(text == null ? null : text + ". See Milestone history in milestone actions for dates and targets.");
        achievementNoteLabel.setVisible(text != null && !text.isEmpty());
        revalidate();
    }

    public void setGoalStatus(MilestoneStatus status) {
        MilestoneStatus state = status == null ? MilestoneStatus.NOT_STARTED : status;
        statusLabel.setText(state == MilestoneStatus.COMPLETE ? "Complete" : state == MilestoneStatus.IN_PROGRESS ? "In progress" : "Not started");
        statusLabel.setForeground(SegmentedProgressBar.getColorFor(state));
        statusLabel.setToolTipText(null);
        progressBar.setStatus(state);
    }

    public void setDescription(String description) {
        if (description == null || description.trim().isEmpty()) {
            return;
        }
        JTextArea text = new JTextArea(description, 0, 20);
        text.setLineWrap(true);
        text.setWrapStyleWord(true);
        text.setEditable(false);
        text.setOpaque(false);
        text.setForeground(MUTED_COLOR);
        text.setFont(UiTypography.BODY);
        text.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
        text.setAlignmentX(LEFT_ALIGNMENT);
        content.add(text);
        expandButton.setVisible(true);
    }

    public void setEditAction(ActionListener action) {
        for (ActionListener listener : editButton.getActionListeners()) {
            editButton.removeActionListener(listener);
        }

        if (action != null) {
            editButton.addActionListener(action);
            editButton.setVisible(true);
        } else {
            editButton.setVisible(false);
        }

        revalidate();
        repaint();
    }

    public void setGoalActions(ActionListener edit, ActionListener delete) {
        JPopupMenu menu = new JPopupMenu();
        if (edit != null) {
            JMenuItem editTarget = new JMenuItem("Edit...");
            editTarget.setToolTipText("Edit the milestone target, or a custom milestone's details and manual progress.");
            editTarget.addActionListener(edit);
            menu.add(editTarget);
        }
        JMenuItem remove = new JMenuItem("Delete...");
        remove.setToolTipText("Remove this milestone after confirmation. Game progress is unaffected; Undo restores the last deletion.");
        remove.addActionListener(delete);
        menu.add(remove);
        setEditAction(event -> menu.show(editButton, 0, editButton.getHeight()));
        setComponentPopupMenu(menu);
        titleLabel.setComponentPopupMenu(menu);
    }
    public void addGoalAction(String title, String tooltip, ActionListener listener) {
        JPopupMenu menu = getComponentPopupMenu();
        if (menu == null) {
            return;
        }
        JMenuItem item = new JMenuItem(title);
        item.setToolTipText(tooltip);
        item.addActionListener(listener);
        menu.add(item);
    }

    public void setTitle(String title) {
        String next = title == null ? "" : title;

        if (Objects.equals(this.title, next)) {
            return;
        }

        this.title = next;
        titleLabel.setText(next);
        titleLabel.setToolTipText(next);
        iconLabel.setToolTipText(next);
        revalidate();
        repaint();
    }

    public void setIcon(BufferedImage icon) {
        if (this.icon == icon) {
            return;
        }

        this.icon = icon;
        iconLabel.setIcon(icon == null ? null : new ImageIcon(icon));
        iconLabel.setPreferredSize(new Dimension(icon == null ? 24 : Math.max(24, icon.getWidth()), icon == null ? 24 : Math.max(24, icon.getHeight())));
        if (icon instanceof AsyncBufferedImage) {
            ((AsyncBufferedImage) icon).addTo(iconLabel);
        }
        iconLabel.setVisible(iconVisible && icon != null);
        revalidate();
        repaint();
    }

    public void setProgress(long current, long maximum, String text) {
        long nextCurrent = Math.max(0, current);
        long nextMaximum = Math.max(0, maximum);
        String nextText = text == null ? "" : text;

        if (progressCurrent == nextCurrent && progressMaximum == nextMaximum && Objects.equals(progressText, nextText)) {
            return;
        }

        progressCurrent = nextCurrent;
        progressMaximum = nextMaximum;
        progressText = nextText;
        progressStatus = "";
        updateProgress();
    }

    public void setProgressStatus(String status) {
        String next = status == null ? "" : status;

        if (Objects.equals(progressStatus, next)) {
            return;
        }

        progressStatus = next;
        progressText = next;
        updateProgress();
    }

    public void setIconVisible(boolean visible) {
        if (iconVisible == visible) {
            return;
        }

        iconVisible = visible;
        iconLabel.setVisible(visible && icon != null);
        revalidate();
        repaint();
    }

    public void setProgressBarVisible(boolean visible) {
        if (progressBarVisible == visible) {
            return;
        }

        progressBarVisible = visible;
        progressBar.setVisible(visible);
        revalidate();
        repaint();
    }

    public void setExpanded(boolean expanded) {
        if (this.expanded == expanded) {
            return;
        }

        this.expanded = expanded;
        content.setVisible(expanded);
        footer.setVisible(true);
        expandButton.setText(expanded ? "−" : "+");
        expandButton.setToolTipText(expanded ? "Collapse milestone details" : "Expand milestone details");
        if (expansionListener != null) {
            expansionListener.accept(expanded);
        }
        revalidate();
        repaint();
    }

    private void applyValues() {
        titleLabel.setText(title);
        titleLabel.setToolTipText(title);
        iconLabel.setToolTipText(title);
        iconLabel.setIcon(icon == null ? null : new ImageIcon(icon));
        iconLabel.setVisible(iconVisible && icon != null);
        updateProgress();
        content.setVisible(expanded);
        footer.setVisible(true);
        expandButton.setText(expanded ? "−" : "+");
        progressBar.setVisible(progressBarVisible);
    }

    private void updateProgress() {
        expandButton.setVisible(content.getComponentCount() > 0);
        progressBar.setProgress(progressCurrent, progressMaximum);
        setGoalStatus(progressMaximum > 0 && progressCurrent >= progressMaximum ? MilestoneStatus.COMPLETE : progressCurrent > 0 ? MilestoneStatus.IN_PROGRESS : MilestoneStatus.NOT_STARTED);
        progressLabel.setText(progressMaximum > 0 && progressStatus.isEmpty() ? String.format(Locale.ROOT, "%s (%.1f%%)", progressText, Math.min(100.0, progressCurrent * 100.0 / progressMaximum)) : progressText);
        progressLabel.setToolTipText(null);
        progressBar.setToolTipText(null);
        progressBar.setVisible(progressBarVisible);
        revalidate();
        repaint();
    }

    private void refreshLayout() {
        applyValues();
        revalidate();
        repaint();
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }
}

package com.grindstone.ui.components;

import com.grindstone.repository.MilestoneMetadata;
import com.grindstone.repository.RecurringMilestone;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.time.Instant;
import java.time.ZoneOffset;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.function.Supplier;
import javax.swing.*;
import javax.swing.table.DefaultTableCellRenderer;
import javax.swing.table.DefaultTableModel;
import net.runelite.client.ui.FontManager;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public final class MilestoneHistoryPanel extends JPanel {
    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm 'UTC'").withZone(ZoneOffset.UTC);
    public static Supplier<MilestoneHistoryPanel> createSnapshot(MilestoneMetadata metadata) {
        List<Object[]> periods = new ArrayList<>();
        List<Object[]> milestones = new ArrayList<>();
        RecurringMilestone recurring = metadata.getRecurring();
        if (recurring.isActive()) {
            periods.add(new Object[]{recurring.getSchedule(), date(recurring.getStart()), recurring.getBaselineAt() == 0 ? "—" : date(recurring.getSchedule().getNextReset(recurring.getStart())), recurring.getProgress(), recurring.getTarget(), recurring.getBaselineAt() == 0 ? "Waiting for login" : recurring.getCompletedAt() > 0 ? "Completed · current period" : "Current period", date(recurring.getBaselineAt()), date(recurring.getLastObservedAt()), date(recurring.getCompletedAt())});
        }
        List<RecurringMilestone.Period> history = recurring.getHistory();
        for (int index = history.size() - 1; index >= 0; index--) {
            RecurringMilestone.Period period = history.get(index);
            periods.add(new Object[]{period.getSchedule(), date(period.getStart()), date(period.getEnd()), period.getBaselineAt() == 0 ? null : period.getProgress(), period.getTarget(), period.getOutcome(), date(period.getBaselineAt()), date(period.getLastObservedAt()), date(period.getCompletedAt())});
        }
        List<MilestoneMetadata.Completion> completions = metadata.getCompletions();
        for (int index = completions.size() - 1; index >= 0; index--) {
            MilestoneMetadata.Completion event = completions.get(index);
            milestones.add(new Object[]{event.getTitle(), event.getTarget(), date(event.getObservedAt())});
        }
        boolean showPeriods = recurring.isActive() || !history.isEmpty();
        return () -> new MilestoneHistoryPanel(periods, milestones, showPeriods);
    }
    private MilestoneHistoryPanel(List<Object[]> periodRows, List<Object[]> milestoneRows, boolean showPeriods) {
        super(new BorderLayout(0, 10));
        JTabbedPane tabs = new JTabbedPane();
        DefaultTableModel periods = model("Schedule", "Period start", "Period end", "Progress", "Target", "Outcome", "Baseline captured", "Last observed", "Completed at");
        periodRows.forEach(periods::addRow);
        DefaultTableModel milestones = model("Milestone", "Target", "First observed completed");
        milestoneRows.forEach(milestones::addRow);
        tabs.addTab("Periods (" + periodRows.size() + ")", table(periods));
        tabs.addTab("Lifetime targets (" + milestoneRows.size() + ")", table(milestones));
        if (!showPeriods) {
            tabs.setSelectedIndex(1);
        }
        JLabel note = new JLabel("<html>Times are UTC. Progress starts from the captured baseline, not an assumed offline reset value.<br>Incomplete values are last observed; unobserved gaps are not counted as misses. Latest 500 period records retained.<br>Completion dates are first observed, not historical achievement dates.</html>");
        note.setFont(FontManager.getRunescapeSmallFont());
        add(note, BorderLayout.NORTH);
        add(tabs, BorderLayout.CENTER);
        setPreferredSize(new Dimension(700, 340));
    }
    private static String date(long value) {
        return value <= 0 ? "—" : DATE.format(Instant.ofEpochMilli(value));
    }
    private static DefaultTableModel model(String... columns) {
        return new DefaultTableModel(columns, 0) {
            @Override
            public boolean isCellEditable(int row, int column) {
                return false;
            }
            @Override
            public Class<?> getColumnClass(int column) {
                for (int row = 0; row < getRowCount(); row++) {
                    if (getValueAt(row, column) instanceof Long) {
                        return Long.class;
                    }
                }
                return Object.class;
            }
        };
    }
    private static JScrollPane table(DefaultTableModel model) {
        JTable table = new JTable(model);
        table.setFont(FontManager.getRunescapeFont());
        table.setRowHeight(26);
        table.setAutoCreateRowSorter(true);
        table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);
        table.setDefaultRenderer(Long.class, new DefaultTableCellRenderer() {
            @Override
            protected void setValue(Object value) {
                setHorizontalAlignment(SwingConstants.RIGHT);
                setText(value == null ? "—" : String.format(Locale.ROOT, "%,d", value));
            }
        });
        table.getTableHeader().setReorderingAllowed(false);
        for (int column = 0; column < model.getColumnCount(); column++) {
            table.getColumnModel().getColumn(column).setPreferredWidth(model.getColumnClass(column) == Long.class ? 95 : 175);
        }
        table.setToolTipText("Scroll horizontally for observation dates. Click a heading to sort; rows cannot be edited.");
        JScrollPane scroll = new JScrollPane(table);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        return scroll;
    }
}

