        } else {
            addRow(new SkillExperienceMilestone(Skill.WOODCUTTING), 100_000);
            addRow(new SkillExperienceMilestone(Skill.FISHING), 50_000);
            addRow(new TrackerMilestone(TrackerEntry.WINTERTODT, 1), 3);
        }
