package com.grindstone.repository;

import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.Executor;
import net.runelite.client.util.Filepath;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import static org.junit.Assert.*;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public class ProfilePersistenceTest {
    @Rule
    public TemporaryFolder temporary = new TemporaryFolder();

    @Test
    public void migratesLocalProfileAndPrefersSyncedDataOnAnotherComputer() throws Exception {
        Filepath first = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
        Filepath second = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
        TestProfiles.REPOSITORY.save(first.joinSegment("profiles"), TestProfiles.REPOSITORY.toJson(TestProfiles.populated(42)));
        MemoryProfiles settings = new MemoryProfiles();
        ProfilePersistence source = new ProfilePersistence(TestProfiles.REPOSITORY, Runnable::run, settings);
        source.configure(() -> first);
        GrindstoneProfile migrated = source.load(42).join();
        assertEquals(1, migrated.getGoals().size());
        assertNotNull(settings.values.get("first"));
        assertTrue(first.joinSegment("profiles").joinSegment("42.json").exists());
        migrated.getMetadata(migrated.getGoals().get(0)).setPinned(true);
        source.save(TestProfiles.REPOSITORY.toJson(migrated)).join();
        TestProfiles.REPOSITORY.save(second.joinSegment("profiles"), TestProfiles.REPOSITORY.toJson(new GrindstoneProfile(42)));
        ProfilePersistence destination = new ProfilePersistence(TestProfiles.REPOSITORY, Runnable::run, settings);
        destination.configure(() -> second);
        GrindstoneProfile restored = destination.load(42).join();
        assertEquals(1, restored.getGoals().size());
        assertTrue(restored.getMetadata(restored.getGoals().get(0)).isPinned());
        settings.values.put("first", TestProfiles.REPOSITORY.exportBackup(TestProfiles.populated(99)));
        try {
            destination.load(42).join();
            fail("A different account's synced data must be rejected");
        } catch (CompletionException expected) {
            assertTrue(expected.getCause() instanceof IOException);
        }
    }

    @Test
    public void queuedSavesKeepTheirOriginalCharacterProfile() throws Exception {
        Queue<Runnable> scheduled = new ArrayDeque<>();
        MemoryProfiles settings = new MemoryProfiles();
        ProfilePersistence persistence = new ProfilePersistence(TestProfiles.REPOSITORY, scheduled::add, settings);
        Filepath root = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
        persistence.configure(() -> root);
        persistence.load(42);
        settings.current = "second";
        persistence.load(99);
        persistence.save(TestProfiles.REPOSITORY.toJson(TestProfiles.populated(42)));
        while (!scheduled.isEmpty()) {
            scheduled.remove().run();
        }
        assertEquals(1, TestProfiles.REPOSITORY.readProfile(settings.values.get("first"), 42).getGoals().size());
        assertTrue(TestProfiles.REPOSITORY.readProfile(settings.values.get("second"), 99).getGoals().isEmpty());
    }

    @Test
    public void syncLimitKeepsLastSyncedValueAndSavesLocalRecovery() throws Exception {
        MemoryProfiles settings = new MemoryProfiles();
        ProfilePersistence persistence = new ProfilePersistence(TestProfiles.REPOSITORY, Runnable::run, settings);
        Filepath root = Filepath.Unchecked.getRooted(temporary.newFolder().toPath());
        persistence.configure(() -> root);
        persistence.load(42).join();
        JsonObject snapshot = TestProfiles.REPOSITORY.toJson(TestProfiles.populated(42));
        snapshot.addProperty("padding", "");
        char[] padding = new char[ProfilePersistence.MAX_SYNC_CHARACTERS - snapshot.toString().length()];
        Arrays.fill(padding, 'x');
        snapshot.addProperty("padding", new String(padding));
        persistence.save(snapshot).join();
        String previous = settings.values.get("first");
        assertEquals(ProfilePersistence.MAX_SYNC_CHARACTERS, previous.length());
        snapshot.addProperty("padding", new String(padding) + "x");
        snapshot.getAsJsonArray("goals").get(0).getAsJsonObject().getAsJsonObject("metadata").addProperty("pinned", true);
        try {
            persistence.save(snapshot).join();
            fail("An oversized profile must not replace synced data");
        } catch (CompletionException expected) {
            assertTrue(expected.getCause() instanceof ProfilePersistence.SyncLimitException);
        }
        assertEquals(previous, settings.values.get("first"));
        assertEquals(1, TestProfiles.REPOSITORY.load(root.joinSegment("profiles"), 42).getGoals().size());
        ProfilePersistence restarted = new ProfilePersistence(TestProfiles.REPOSITORY, Runnable::run, settings);
        restarted.configure(() -> root);
        GrindstoneProfile recovered = restarted.load(42).join();
        assertTrue(recovered.getMetadata(recovered.getGoals().get(0)).isPinned());
        restarted.save(TestProfiles.REPOSITORY.toJson(recovered)).join();
        assertFalse(root.joinSegment("profiles").joinSegment("42.sync-pending").exists());
        GrindstoneProfile synced = TestProfiles.REPOSITORY.readProfile(settings.values.get("first"), 42);
        assertTrue(synced.getMetadata(synced.getGoals().get(0)).isPinned());
    }

    /**
     * @author Ayman Yassen
     * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
     * @since 10/21/2026
     */
    private static final class MemoryProfiles implements ProfilePersistence.SyncedProfiles {
        private final Map<String, String> values = new HashMap<>();
        private String current = "first";

        @Override
        public String prepareProfile() {
            return current;
        }

        @Override
        public String read(String profileKey) {
            return values.get(profileKey);
        }

        @Override
        public void write(String profileKey, String text) {
            values.put(profileKey, text);
        }
    }

    @Test
    public void cancellingCallerDoesNotSkipQueuedWork() {
        Queue<Runnable> scheduled = new ArrayDeque<>();
        ProfilePersistence persistence = new ProfilePersistence(TestProfiles.REPOSITORY, (Executor) scheduled::add);
        List<Integer> order = new ArrayList<>();
        CompletableFuture<Integer> first = persistence.enqueue(() -> {
            order.add(1);
            return 1;
        });
        persistence.enqueue(() -> order.add(2));
        first.cancel(false);
        assertEquals(1, scheduled.size());
        scheduled.remove().run();
        assertEquals(Arrays.asList(1), order);
        scheduled.remove().run();
        assertEquals(Arrays.asList(1, 2), order);
    }

    @Test
    public void queuesWorkWithoutBlockingAndRecoversAfterFailure() {
        Queue<Runnable> scheduled = new ArrayDeque<>();
        ProfilePersistence persistence = new ProfilePersistence(TestProfiles.REPOSITORY, (Executor) scheduled::add);
        List<Integer> order = new ArrayList<>();
        CompletableFuture<Integer> first = persistence.enqueue(() -> {
            order.add(1);
            throw new IOException("Simulated disk failure");
        });
        CompletableFuture<Integer> second = persistence.enqueue(() -> {
            order.add(2);
            return 2;
        });
        assertFalse(first.isDone());
        assertFalse(second.isDone());
        assertEquals(1, scheduled.size());
        scheduled.remove().run();
        assertTrue(first.isCompletedExceptionally());
        assertFalse(second.isDone());
        scheduled.remove().run();
        assertEquals(Integer.valueOf(2), second.getNow(null));
        assertEquals(Arrays.asList(1, 2), order);
    }

    @Test
    public void metadataCopyDoesNotShareMutablePeriodState() {
        MilestoneMetadata original = new MilestoneMetadata();
        original.getRecurring().configure(RepeatSchedule.DAILY, 5, 1000);
        MilestoneMetadata copy = original.copy();
        copy.setPinned(true);
        copy.getRecurring().configure(RepeatSchedule.WEEKLY, 10, 2000);
        assertEquals(original.getId(), copy.getId());
        assertFalse(original.isPinned());
        assertEquals(RepeatSchedule.DAILY, original.getRecurring().getSchedule());
        assertEquals(5, original.getRecurring().getTarget());
    }
}

package com.grindstone.repository;

import com.grindstone.content.milestone.MilestoneCategory;
import com.grindstone.content.milestone.impl.CustomMilestone;
import com.grindstone.content.milestone.impl.experience.SkillExperienceMilestone;
import java.time.Instant;
import java.util.Collections;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/19/2026
 */
public class RecurringMilestoneTest {
    @Test
    public void restartingArchivesObservedProgressWithoutChangingTheSchedule() {
        CustomMilestone goal = new CustomMilestone("Daily", "", MilestoneCategory.OTHER, 2, 5);
        RecurringMilestone recurring = new RecurringMilestone();
        long now = time("2026-10-19T10:00:00Z");
        recurring.configure(RepeatSchedule.DAILY, 5, now);
        recurring.observe(goal, now);
        recurring.restart(now + 1000);
        assertEquals(RepeatSchedule.DAILY, recurring.getSchedule());
        assertEquals(5, recurring.getTarget());
        assertEquals(0, recurring.getBaselineAt());
        assertEquals(1, recurring.getHistory().size());
        assertEquals(2, recurring.getHistory().get(0).getProgress());
        assertEquals("Period restarted · last observed", recurring.getHistory().get(0).getOutcome());
        goal.update("Daily", "", MilestoneCategory.OTHER, 0, 5);
        recurring.observe(goal, now + 2000);
        assertEquals(0, recurring.getProgress());
        assertEquals(now + 2000, recurring.getBaselineAt());
    }
    private long time(String value) {
        return Instant.parse(value).toEpochMilli();
    }
    @Test
    public void usesUtcCalendarBoundaries() {
        long now = time("2026-10-21T12:00:00Z");
        assertEquals(time("2026-10-21T00:00:00Z"), RepeatSchedule.DAILY.getPeriodStart(now));
        assertEquals(time("2026-10-19T00:00:00Z"), RepeatSchedule.WEEKLY.getPeriodStart(now));
        assertEquals(time("2026-11-01T00:00:00Z"), RepeatSchedule.MONTHLY.getNextReset(RepeatSchedule.MONTHLY.getPeriodStart(now)));
        assertEquals(time("2028-03-01T00:00:00Z"), RepeatSchedule.MONTHLY.getNextReset(time("2028-02-01T00:00:00Z")));
    }
    @Test
    public void resetsManualProgressAndKeepsObservedCompletion() {
        CustomMilestone goal = new CustomMilestone("Daily", "", MilestoneCategory.OTHER, 0, 5);
        RecurringMilestone recurring = new RecurringMilestone();
        long now = time("2026-10-19T10:00:00Z");
        recurring.configure(RepeatSchedule.DAILY, 5, now);
        recurring.observe(goal, now);
        goal.update("Daily", "", MilestoneCategory.OTHER, 5, 5);
        recurring.observe(goal, now + 1000);
        assertEquals(5, recurring.getProgress());
        recurring.observe(goal, time("2026-10-20T10:00:00Z"));
        assertEquals(0, goal.getProgressCurrent());
        assertEquals(0, recurring.getProgress());
        assertEquals("Completed", recurring.getHistory().get(0).getOutcome());
        assertEquals(now + 1000, recurring.getHistory().get(0).getCompletedAt());
    }
    @Test
    public void offlineGapsAreNotInventedMissesAndPersist() {
        GrindstoneProfile profile = TestProfiles.populated(42);
        CustomMilestone goal = new CustomMilestone("Daily", "", MilestoneCategory.OTHER, 2, 5);
        profile.replace(Collections.singletonList(goal));
        RecurringMilestone recurring = profile.getMetadata(goal).getRecurring();
        long now = time("2026-10-19T10:00:00Z");
        recurring.configure(RepeatSchedule.DAILY, 5, now);
        recurring.observe(goal, now);
        recurring.observe(goal, time("2026-11-01T10:00:00Z"));
        assertEquals(2, recurring.getHistory().size());
        assertEquals("Not observed", recurring.getHistory().get(1).getOutcome());
        GrindstoneProfile loaded = TestProfiles.REPOSITORY.fromJson(TestProfiles.REPOSITORY.toJson(profile));
        RecurringMilestone restored = loaded.getMetadata(loaded.getGoals().get(0)).getRecurring();
        assertEquals(RepeatSchedule.DAILY, restored.getSchedule());
        assertEquals(2, restored.getHistory().size());
        assertEquals(recurring.getBaselineAt(), restored.getBaselineAt());
    }
    @Test
    public void automaticCountersCountGainsNotExistingTotals() {
        long[] value = {1_000_000};
        SkillExperienceMilestone goal = new SkillExperienceMilestone(Skill.ATTACK) {
            @Override
            public long getProgressCurrent() {
                return value[0];
            }
        };
        RecurringMilestone recurring = new RecurringMilestone();
        long now = time("2026-10-19T10:00:00Z");
        recurring.configure(RepeatSchedule.DAILY, 100, now);
        recurring.observe(goal, now);
        assertEquals(0, recurring.getProgress());
        value[0] += 60;
        recurring.observe(goal, now + 1);
        assertEquals(60, recurring.getProgress());
        value[0] += 90;
        recurring.observe(goal, time("2026-10-20T10:00:00Z"));
        assertEquals(0, recurring.getProgress());
        assertEquals(60, recurring.getHistory().get(0).getProgress());
        value[0] += 20;
        recurring.observe(goal, time("2026-10-20T10:00:01Z"));
        assertEquals(20, recurring.getProgress());
    }
    @Test
    public void sameSettingsPreserveProgressAndChangesArchiveTheOldTarget() {
        CustomMilestone goal = new CustomMilestone("Daily", "", MilestoneCategory.OTHER, 2, 5);
        RecurringMilestone recurring = new RecurringMilestone();
        long now = time("2026-10-19T00:00:00Z");
        recurring.configure(RepeatSchedule.DAILY, 5, now);
        recurring.observe(goal, now);
        recurring.configure(RepeatSchedule.DAILY, 5, now);
        assertEquals(2, recurring.getProgress());
        assertTrue(recurring.getHistory().isEmpty());
        recurring.configure(RepeatSchedule.WEEKLY, 10, now);
        recurring.validate();
        assertEquals(5, recurring.getHistory().get(0).getTarget());
        assertEquals("Schedule changed", recurring.getHistory().get(0).getOutcome());
        assertEquals(0, recurring.getBaselineAt());
    }
    @Test
    public void transferredBackupsKeepSchedulesButNotAnotherPlayersPeriods() {
        GrindstoneProfile profile = TestProfiles.populated(42);
        CustomMilestone goal = new CustomMilestone("Daily", "", MilestoneCategory.OTHER, 2, 5);
        profile.replace(Collections.singletonList(goal));
        RecurringMilestone recurring = profile.getMetadata(goal).getRecurring();
        long now = time("2026-10-19T10:00:00Z");
        recurring.configure(RepeatSchedule.DAILY, 5, now);
        recurring.observe(goal, now);
        recurring.observe(goal, time("2026-10-20T10:00:00Z"));
        GrindstoneProfile restored = TestProfiles.REPOSITORY.importBackup(TestProfiles.REPOSITORY.exportBackup(profile), 99);
        RecurringMilestone transferred = restored.getMetadata(restored.getGoals().get(0)).getRecurring();
        assertEquals(RepeatSchedule.DAILY, transferred.getSchedule());
        assertEquals(5, transferred.getTarget());
        assertEquals(0, transferred.getBaselineAt());
        assertTrue(transferred.getHistory().isEmpty());
    }
    @Test
    public void retainsOnlyTheLatestFiveHundredPeriodsAndIgnoresClockRollback() {
        CustomMilestone goal = new CustomMilestone("Daily", "", MilestoneCategory.OTHER, 0, 5);
        RecurringMilestone recurring = new RecurringMilestone();
        long now = time("2026-10-19T10:00:00Z");
        recurring.configure(RepeatSchedule.DAILY, 5, now);
        for (int index = 0; index < 510; index++) {
            recurring.observe(goal, now + index * 86_400_000L);
        }
        assertEquals(500, recurring.getHistory().size());
        long baseline = recurring.getBaselineAt();
        recurring.observe(goal, now);
        assertEquals(baseline, recurring.getBaselineAt());
        recurring.validate();
    }
}

package com.grindstone.repository;
import com.google.gson.JsonObject;
import com.grindstone.content.milestone.Milestone;
import com.grindstone.content.milestone.impl.item.PossessedItemMilestone;
import com.grindstone.ui.editor.CompletionMilestoneChoices;
import java.util.Collections;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;
/**
 * @author Ayman Yassen
 * @see <a href="https://discord.gg/l.e.g.e.n.d.a.r.y">Discord</a>
 * @since 10/18/2026
 */
public class SavedMilestoneTypesTest {
    @Test
    public void newlySavedProfilesContainOnlyStableTypeTagsNotJavaClassNames() {
        String json = TestProfiles.REPOSITORY.exportBackup(TestProfiles.populated(42));
        assertTrue(json.contains("\"type\""));
        assertFalse(json.contains("\"class\""));
        assertFalse(json.contains("com.grindstone."));
    }
    @Test
    public void goalsUseStableTagsWithoutClassNameAliases() {
        PossessedItemMilestone goal = new PossessedItemMilestone(ItemID.COINS, 1_500_000_000L);
        assertEquals("owned-item", SavedMilestoneTypes.nameOf(goal));
        assertSame(PossessedItemMilestone.class, SavedMilestoneTypes.resolve(SavedMilestoneTypes.nameOf(goal)));
        assertNull(SavedMilestoneTypes.resolve(PossessedItemMilestone.class.getName()));
    }
    @Test
    public void stableTagsRestoreTheSameSelections() {
        GrindstoneProfile profile = TestProfiles.populated(42);
        CompletionMilestoneChoices.create(null).values().forEach(choices -> choices.values().forEach(factory -> profile.add(factory.get())));
        profile.add(new PossessedItemMilestone(ItemID.COINS, 3_000_000_000L));
        JsonObject json = TestProfiles.REPOSITORY.toJson(profile);
        for (int i = 0; i < profile.getGoals().size(); i++) {
            Milestone goal = profile.getGoals().get(i);
            assertSame(goal.getClass(), SavedMilestoneTypes.resolve(SavedMilestoneTypes.nameOf(goal)));
        }
        GrindstoneProfile restored = TestProfiles.REPOSITORY.fromJson(json);
        assertEquals(profile.getGoals().size(), restored.getGoals().size());
        for (int i = 0; i < profile.getGoals().size(); i++) {
            assertEquals(profile.getGoals().get(i).getClass(), restored.getGoals().get(i).getClass());
        }
    }
    @Test
    public void arbitraryClassNamesRemainBlocked() {
        assertNull(SavedMilestoneTypes.resolve("java.lang.Runtime"));
        assertNull(SavedMilestoneTypes.resolve("com.example.ExamplePlugin"));
        GrindstoneProfile profile = TestProfiles.populated(42);
        profile.replace(Collections.singletonList(new PossessedItemMilestone(ItemID.COINS)));
        JsonObject json = TestProfiles.REPOSITORY.toJson(profile);
        json.getAsJsonArray("goals").get(0).getAsJsonObject().addProperty("class", "java.lang.Runtime");
        assertTrue(TestProfiles.REPOSITORY.fromJson(json).getGoals().isEmpty());
    }
}

